	public class Scenes
	{
		public static string SceneName = "";

		private static readonly string[] SceneMenuNames = new string[4] { "ClientSplash", "PersistentUI", "Login", "CharacterSelectScene" };

		public static bool IsGameScene()
		{
			if (!string.IsNullOrWhiteSpace(SceneName) && !Enumerable.Contains(SceneMenuNames, SceneName))
			{
				return true;
			}
			return false;
		}

		public static bool IsCharacterSelection()
		{
			if (!string.IsNullOrWhiteSpace(SceneName) && SceneName.Contains(SceneMenuNames[3]))
			{
				return true;
			}
			return false;
		}
	}
