		public static GameObject GetChild(GameObject obj, string name)
		{
			GameObject result = null;
			if (!obj.IsNullOrDestroyed())
			{
				bool flag = false;
				for (int i = 0; i < obj.transform.childCount; i++)
				{
					string name2 = ((Object)((Component)obj.transform.GetChild(i)).gameObject).name;
					if (name2 == name)
					{
						result = ((Component)obj.transform.GetChild(i)).gameObject;
						flag = true;
						break;
					}
				}
				string[] source = new string[5] { "skin", "Modifier Button", "legendary_icon", "quad_stash_row", "Hud_VirtualKeyboard" };
				if (!flag && !Enumerable.Contains(source, name))
				{
					Instance logger_instance = Main.logger_instance;
					if (logger_instance != null)
					{
						logger_instance.Error("Functions.GetChild, Child : " + name + " not Found");
					}
				}
			}
			else
			{
				Main.logger_instance.Error("GetChild(" + name + ") : Obj is null");
			}
			return result;
		}

