			{
				[HarmonyPostfix]
				private static void Postfix(ref Button __instance)
				{
					if (!Content.OdlForceDrop.enable || !((Object)__instance).name.Contains(Content.OdlForceDrop.shard_btn_name))
					{
						return;
					}
					try
					{
						int id = Convert.ToInt32(((Object)__instance).name.Split('_')[1]);
						GameObject child = Functions.GetChild(((Component)__instance).gameObject, "shard_name");
						if (!child.IsNullOrDestroyed())
						{
							GameObject child2 = Functions.GetChild(child, "Text");
							if (!child2.IsNullOrDestroyed())
							{
								Text component = child2.GetComponent<Text>();
								Content.OdlForceDrop.SelectShard(id, component.text);
							}
						}
					}
					catch
					{
					}
				}
			}

			[HarmonyPatch(typeof(Toggle), "OnPointerClick")]
			public class Toggle_OnPointerClick
			{
				[HarmonyPostfix]
				private static void Postfix(ref Toggle __instance, PointerEventData __0)
				{
					if (hud_object.IsNullOrDestroyed() || Save_Manager.instance.IsNullOrDestroyed() || Refs_Manager.player_data.IsNullOrDestroyed() || !hud_object.active)
					{
						return;
					}
					if (((Object)__instance).name.Contains("Toggle_Character_"))
					{
						switch (((Object)__instance).name)
						{
						case "Toggle_Character_Data_Died":
							if (!Refs_Manager.player_data.IsNullOrDestroyed() && !Content.Character.Data.died_toggle.IsNullOrDestroyed())
							{
								Refs_Manager.player_data.Died = Content.Character.Data.died_toggle.isOn;
							}
							break;
						case "Toggle_Character_Data_Hardcore":
							if (!Refs_Manager.player_data.IsNullOrDestroyed() && !Content.Character.Data.hardcore_toggle.IsNullOrDestroyed())
							{
								Refs_Manager.player_data.Hardcore = Content.Character.Data.hardcore_toggle.isOn;
							}
							break;
						case "Toggle_Character_Data_Masochist":
							if (!Refs_Manager.player_data.IsNullOrDestroyed() && !Content.Character.Data.masochist_toggle.IsNullOrDestroyed())
							{
								Refs_Manager.player_data.Masochist = Content.Character.Data.masochist_toggle.isOn;
							}
							break;
						case "Toggle_Character_Data_Portal":
							if (!Refs_Manager.player_data.IsNullOrDestroyed() && !Content.Character.Data.portal_toggle.IsNullOrDestroyed())
							{
								Refs_Manager.player_data.PortalUnlocked = Content.Character.Data.portal_toggle.isOn;
							}
							break;
						case "Toggle_Character_Data_SoloChallenge":
							if (!Refs_Manager.player_data.IsNullOrDestroyed() && !Content.Character.Data.solo_toggle.IsNullOrDestroyed())
							{
								Refs_Manager.player_data.SoloChallenge = Content.Character.Data.solo_toggle.isOn;
							}
							break;
						case "Toggle_Character_Buffs_Enable":
							Save_Manager.instance.data.Character.PermanentBuffs.Enable_Mod = __instance.isOn;
							break;
						case "Toggle_Character_Buffs_MoveSpeed":
							Save_Manager.instance.data.Character.PermanentBuffs.Enable_MoveSpeed_Buff = __instance.isOn;
							break;
						case "Toggle_Character_Buffs_Damage":
							Save_Manager.instance.data.Character.PermanentBuffs.Enable_Damage_Buff = __instance.isOn;
							break;
						case "Toggle_Character_Buffs_AttackSpeed":
							Save_Manager.instance.data.Character.PermanentBuffs.Enable_AttackSpeed_Buff = __instance.isOn;
							break;
						case "Toggle_Character_Buffs_CastingSpeed":
