							break;
						case "Toggle_Character_Buffs_CriticalMultiplier":
							Save_Manager.instance.data.Character.PermanentBuffs.Enable_CriticalMultiplier_Buff = __instance.isOn;
							break;
						case "Toggle_Character_Buffs_HealthRegen":
