		public class Events
		{
			public static void Set_Base_Button_Event(GameObject base_obj, string child, string btn_name, UnityAction action)
			{
				//IL_005e: Unknown result type (might be due to invalid IL or missing references)
				//IL_0068: Expected O, but got Unknown
				if (!base_obj.IsNullOrDestroyed())
				{
					GameObject child2 = Functions.GetChild(base_obj, child);
					if (!child2.IsNullOrDestroyed())
					{
						GameObject child3 = Functions.GetChild(child2, btn_name);
						if (!child3.IsNullOrDestroyed())
						{
							Button component = child3.GetComponent<Button>();
							if (!component.IsNullOrDestroyed())
							{
								component.onClick = new ButtonClickedEvent();
								((UnityEvent)component.onClick).AddListener(action);
							}
							else
							{
								Main.logger_instance.Error("Set_Base_Button_Event Can't found button");
							}
						}
						else
						{
							Main.logger_instance.Error("Set_Base_Button_Event Can't found GameObject button " + btn_name);
						}
					}
					else
					{
						Main.logger_instance.Error("Set_Base_Button_Event Can't found " + child + " in base_obj");
					}
				}
				else
				{
					Main.logger_instance.Error("Set_Base_Button_Event base_obj is null");
				}
			}

			public static void Set_Button_Event(Button btn, UnityAction action)
			{
				//IL_0002: Unknown result type (might be due to invalid IL or missing references)
				//IL_000c: Expected O, but got Unknown
				btn.onClick = new ButtonClickedEvent();
				((UnityEvent)btn.onClick).AddListener(action);
			}

			public static void Set_Slider_Event(Slider slider, UnityAction<float> action)
			{
				//IL_0002: Unknown result type (might be due to invalid IL or missing references)
				//IL_000c: Expected O, but got Unknown
				slider.onValueChanged = new SliderEvent();
				((UnityEvent<float>)(object)slider.onValueChanged).AddListener(action);
			}

			public static void Set_Toggle_Event(Toggle toggle, UnityAction<bool> action)
			{
				//IL_0002: Unknown result type (might be due to invalid IL or missing references)
				//IL_000c: Expected O, but got Unknown
				toggle.onValueChanged = new ToggleEvent();
				((UnityEvent<bool>)(object)toggle.onValueChanged).AddListener(action);
			}

			public static void Set_DropDown_Event(Dropdown dropdown, UnityAction<int> action)
			{
				//IL_0002: Unknown result type (might be due to invalid IL or missing references)
				//IL_000c: Expected O, but got Unknown
				dropdown.onValueChanged = new DropdownEvent();
				((UnityEvent<int>)(object)dropdown.onValueChanged).AddListener(action);
			}
		}

		public class Hud_Base
		{
			public static bool Initialized = false;

			public static bool Initializing = false;

			public static bool initiliazed_events = false;

			public static GameObject Default_PauseMenu_Btns = null;

			public static Button Btn_Resume;

			public static Button Btn_Settings;

			public static Button Btn_GameGuide;

			public static Button Btn_LeaveGame;

			public static Button Btn_ExitDesktop;

			public static GameObject ChapterInfo = null;

			public static GameObject Menu_Fade_Background = null;

			public static GameObject Chapter_Fade_Background = null;

			private static readonly Action Resume_OnClick_Action = Resume_Click;

			private static readonly Action Settings_OnClick_Action = Settings_Click;

			private static readonly Action GameGuide_OnClick_Action = GameGuide_Click;

			private static readonly Action LeaveGame_OnClick_Action = LeaveGame_Click;

			private static readonly Action ExitDesktop_OnClick_Action = ExitDesktop_Click;

			public static bool Get_DefaultPauseMenu()
			{
				bool result = false;
				foreach (MainMenuPanel item in Resources.FindObjectsOfTypeAll<MainMenuPanel>())
				{
					if (((Object)item).name.Contains("Clone"))
					{
						game_pause_menu = ((Component)item).gameObject;
						break;
					}
				}
				if (!game_pause_menu.IsNullOrDestroyed())
				{
					Default_PauseMenu_Btns = Functions.GetChild(game_pause_menu, "Menu");
					Get_Refs();
					result = true;
				}
				return result;
			}

			public static void Set_ChapterInfo(bool show)
			{
				if (!Refs_Manager.game_uibase.IsNullOrDestroyed() && !game_pause_menu.IsNullOrDestroyed())
				{
					if (ChapterInfo.IsNullOrDestroyed())
					{
						ChapterInfo = Functions.GetChild(game_pause_menu, "ChapterInfo");
					}
					if (!ChapterInfo.IsNullOrDestroyed())
					{
						ChapterInfo.active = show;
					}
					if (Menu_Fade_Background.IsNullOrDestroyed())
					{
						Menu_Fade_Background = Functions.GetChild(game_pause_menu, "Menu_Fade_Background");
					}
					if (!Menu_Fade_Background.IsNullOrDestroyed())
					{
						Menu_Fade_Background.active = show;
					}
					if (Chapter_Fade_Background.IsNullOrDestroyed())
					{
						Chapter_Fade_Background = Functions.GetChild(game_pause_menu, "Chapter_Fade_Background");
					}
					if (!Chapter_Fade_Background.IsNullOrDestroyed())
					{
						Chapter_Fade_Background.active = show;
					}
				}
			}

			public static bool Get_DefaultPauseMenu_Open()
			{
				if (!Default_PauseMenu_Btns.IsNullOrDestroyed())
				{
					return Default_PauseMenu_Btns.active;
				}
				return false;
			}

			public static void Toogle_DefaultPauseMenu(bool show)
			{
				if (!Default_PauseMenu_Btns.IsNullOrDestroyed())
				{
					Default_PauseMenu_Btns.active = show;
				}
			}

			public static void Get_Refs()
			{
				if (!Default_PauseMenu_Btns.IsNullOrDestroyed())
				{
					GameObject child = Functions.GetChild(Default_PauseMenu_Btns, "Buttons");
					if (!child.IsNullOrDestroyed())
					{
						Btn_Resume = Functions.GetChild(child, "Resume Button").GetComponent<Button>();
						Btn_Settings = Functions.GetChild(child, "Settings Button").GetComponent<Button>();
						Btn_GameGuide = Functions.GetChild(child, "Game Guide Button").GetComponent<Button>();
						Btn_LeaveGame = Functions.GetChild(child, "Character Select Button").GetComponent<Button>();
						Btn_ExitDesktop = Functions.GetChild(child, "Exit Button").GetComponent<Button>();
					}
				}
			}

			public static void Set_Events()
			{
				if (!Default_PauseMenu_Btns.IsNullOrDestroyed() && !hud_object.IsNullOrDestroyed())
				{
					GameObject child = Functions.GetChild(hud_object, "Base");
					if (!child.IsNullOrDestroyed())
					{
						Events.Set_Base_Button_Event(child, "Content", "Btn_Base_Resume", UnityAction.op_Implicit(Resume_OnClick_Action));
						Events.Set_Base_Button_Event(child, "Content", "Btn_Base_Settings", UnityAction.op_Implicit(Settings_OnClick_Action));
						Events.Set_Base_Button_Event(child, "Content", "Btn_Base_GameGuide", UnityAction.op_Implicit(GameGuide_OnClick_Action));
						Events.Set_Base_Button_Event(child, "Content", "Btn_Base_LeaveGame", UnityAction.op_Implicit(LeaveGame_OnClick_Action));
						Events.Set_Base_Button_Event(child, "Content", "Btn_Base_ExitDesktop", UnityAction.op_Implicit(ExitDesktop_OnClick_Action));
						initiliazed_events = true;
					}
				}
			}

			public static void Resume_Click()
			{
				if (!Btn_Resume.IsNullOrDestroyed())
				{
					((UnityEvent)Btn_Resume.onClick).Invoke();
				}
			}

			public static void Settings_Click()
			{
				if (!Btn_Settings.IsNullOrDestroyed())
				{
					((UnityEvent)Btn_Settings.onClick).Invoke();
				}
			}

			public static void GameGuide_Click()
			{
				if (!Btn_GameGuide.IsNullOrDestroyed())
				{
					((UnityEvent)Btn_GameGuide.onClick).Invoke();
				}
			}

			public static void LeaveGame_Click()
			{
				if (Btn_LeaveGame != null)
				{
					Content.Close_AllContent();
					((UnityEvent)Btn_LeaveGame.onClick).Invoke();
				}
			}

			public static void ExitDesktop_Click()
			{
				if (!Btn_ExitDesktop.IsNullOrDestroyed())
				{
					Content.Close_AllContent();
					((UnityEvent)Btn_ExitDesktop.onClick).Invoke();
				}
			}
		}

