						if (monolith_stability_basic_slider.IsNullOrDestroyed() || monolith_stability_basic_text.IsNullOrDestroyed() || monolith_dropdown.IsNullOrDestroyed())
						{
							return;
						}
						int num = Convert.ToInt32(monolith_stability_basic_slider.value);
						int value = monolith_dropdown.value;
						if (!Refs_Manager.player_data.IsNullOrDestroyed())
						{
							Enumerator<SavedMonolithRun> enumerator = Refs_Manager.player_data.MonolithRuns.GetEnumerator();
							while (enumerator.MoveNext())
							{
								SavedMonolithRun current = enumerator.Current;
								if (current.TimelineID == value && current.DifficultyIndex == 0)
								{
									if (current.Stability != num)
									{
										current.Stability = num;
									}
									break;
								}
							}
						}
						monolith_stability_basic_text.text = num.ToString();
					}

