					public static Faction GetFaction()
					{
						//IL_0034: Unknown result type (might be due to invalid IL or missing references)
						//IL_0049: Unknown result type (might be due to invalid IL or missing references)
						//IL_004f: Invalid comparison between Unknown and I4
						//IL_005f: Unknown result type (might be due to invalid IL or missing references)
						//IL_0065: Invalid comparison between Unknown and I4
						//IL_0075: Unknown result type (might be due to invalid IL or missing references)
						//IL_007b: Invalid comparison between Unknown and I4
						Faction result = null;
						if (!Refs_Manager.faction_tracker.IsNullOrDestroyed())
						{
							Enumerator<FactionID, Faction> enumerator = Refs_Manager.faction_tracker.factions.GetEnumerator();
							while (enumerator.MoveNext())
							{
								KeyValuePair<FactionID, Faction> current = enumerator.Current;
								if (((int)current.Key == 0 && factions_dropdown.value == 1) || ((int)current.Key == 1 && factions_dropdown.value == 2) || ((int)current.Key == 2 && factions_dropdown.value == 3) || ((int)current.Key == 3 && factions_dropdown.value == 4))
								{
									result = current.Value;
								}
							}
						}
						return result;
					}

					public static void factions_favor(float f)
					{
						int num = Convert.ToInt32(factions_favor_slider.value);
						if (!factions_favor_text.IsNullOrDestroyed())
						{
							factions_favor_text.text = num.ToString();
						}
					}

					public static void factions_gain_favor_Click()
					{
						if (!factions_favor_slider.IsNullOrDestroyed() && !selected_faction.IsNullOrDestroyed())
						{
							if (!selected_faction.hasEverJoined)
							{
								selected_faction.Join(true);
							}
							if (!selected_faction.IsMember)
							{
								selected_faction.IsMember = true;
							}
							int num = Convert.ToInt32(factions_favor_slider.value);
							int num2 = 999999;
							int num3 = num2 - selected_faction.Favor;
							if (num > num3)
							{
								num = num3;
							}
							selected_faction.GainFavor(num, false, false);
							selected_faction.SaveAndSync(false);
						}
						else
						{
							Main.logger_instance.Error("Faction not found");
						}
					}

					public static void factions_set_favor_Click()
					{
						if (!factions_favor_slider.IsNullOrDestroyed() && !selected_faction.IsNullOrDestroyed())
						{
							if (!selected_faction.hasEverJoined)
							{
								selected_faction.Join(true);
							}
							if (!selected_faction.IsMember)
							{
								selected_faction.IsMember = true;
							}
							int num = Convert.ToInt32(factions_favor_slider.value);
							int num2 = 999999;
							int num3 = num2 - selected_faction.Favor;
							if (num > num3)
							{
								num = num3;
							}
							selected_faction.Favor = num;
							selected_faction.SaveAndSync(false);
						}
						else
						{
							Main.logger_instance.Error("Faction not found");
						}
					}

					public static void factions_rank(float f)
					{
						int num = Convert.ToInt32(factions_rank_slider.value);
						if (!factions_rank_text.IsNullOrDestroyed())
						{
							factions_rank_text.text = num.ToString();
						}
					}

					public static void factions_set_rank_Click()
					{
						if (!factions_rank_slider.IsNullOrDestroyed() && !selected_faction.IsNullOrDestroyed())
						{
							if (!selected_faction.hasEverJoined)
							{
								selected_faction.Join(true);
							}
							if (!selected_faction.IsMember)
							{
								selected_faction.IsMember = true;
							}
							int num = 12;
							if (factions_dropdown.value == 3 || factions_dropdown.value == 4)
							{
								num = 10;
							}
							int num2 = Convert.ToInt32(factions_rank_slider.value);
							if (num2 > num)
							{
								num2 = num;
							}
							selected_faction.Rank = num2;
							selected_faction.SaveAndSync(false);
						}
						else
						{
							Main.logger_instance.Error("Faction not found");
						}
					}

					public static void factions_reputation(float f)
					{
						int num = Convert.ToInt32(factions_reputation_slider.value);
						if (!factions_reputation_text.IsNullOrDestroyed())
						{
							factions_reputation_text.text = num.ToString();
						}
					}

					public static void factions_set_reputation_Click()
					{
						if (!factions_reputation_slider.IsNullOrDestroyed() && !selected_faction.IsNullOrDestroyed())
						{
							if (!selected_faction.hasEverJoined)
							{
								selected_faction.Join(true);
							}
							if (!selected_faction.IsMember)
							{
								selected_faction.IsMember = true;
							}
							int num = Convert.ToInt32(factions_reputation_slider.value);
							int totalReputation = selected_faction.TotalReputation;
							if (num > totalReputation)
							{
								num = totalReputation;
							}
							selected_faction.Reputation = num;
							selected_faction.SaveAndSync(false);
						}
						else
						{
							Main.logger_instance.Error("Faction not found");
						}
					}
				}

