				public static void Update_Monoliths_Data()
				{
					if (Refs_Manager.player_data.IsNullOrDestroyed() || Data.monolith_dropdown.IsNullOrDestroyed() || Data.monolith_stability_basic_go.IsNullOrDestroyed() || Data.monolith_stability_basic_slider.IsNullOrDestroyed() || Data.monolith_stability_basic_text.IsNullOrDestroyed() || Data.monolith_stability_empower_go.IsNullOrDestroyed() || Data.monolith_stability_empower_slider.IsNullOrDestroyed() || Data.monolith_stability_empower_text.IsNullOrDestroyed() || Data.monolith_corruption_go.IsNullOrDestroyed() || Data.monolith_corruption_slider.IsNullOrDestroyed() || Data.monolith_corruption_text.IsNullOrDestroyed() || Data.monolith_gaze_go.IsNullOrDestroyed() || Data.monolith_gaze_slider.IsNullOrDestroyed() || Data.monolith_gaze_text.IsNullOrDestroyed())
					{
						return;
					}
					int value = Data.monolith_dropdown.value;
					if (value < 1)
					{
						int num = -1;
						Data.monolith_stability_basic_go.active = false;
						Data.monolith_stability_basic_slider.value = num;
						Data.monolith_stability_basic_text.text = num.ToString();
						Data.monolith_stability_empower_go.active = false;
						Data.monolith_stability_empower_slider.value = num;
						Data.monolith_stability_empower_text.text = num.ToString();
						Data.monolith_corruption_go.active = false;
						Data.monolith_corruption_slider.value = num;
						Data.monolith_corruption_text.text = num.ToString();
						Data.monolith_gaze_go.active = false;
						Data.monolith_gaze_slider.value = num;
						Data.monolith_gaze_text.text = num.ToString();
						return;
					}
					SavedMonolithRun val = null;
					SavedMonolithRun val2 = null;
					Enumerator<SavedMonolithRun> enumerator = Refs_Manager.player_data.MonolithRuns.GetEnumerator();
					while (enumerator.MoveNext())
					{
						SavedMonolithRun current = enumerator.Current;
						if (current.TimelineID == value)
						{
							if (current.DifficultyIndex == 0)
							{
								val = current;
							}
							else
							{
								val2 = current;
							}
						}
					}
					if (!val.IsNullOrDestroyed())
					{
						Data.monolith_stability_basic_go.active = true;
						int stability = val.Stability;
						Data.monolith_stability_basic_slider.value = stability;
						Data.monolith_stability_basic_text.text = stability.ToString();
					}
					else
					{
						Data.monolith_stability_basic_go.active = false;
						int num2 = -1;
						Data.monolith_stability_basic_slider.value = num2;
						Data.monolith_stability_basic_text.text = num2.ToString();
					}
					if (!val2.IsNullOrDestroyed())
					{
						Data.monolith_stability_empower_go.active = true;
						int stability2 = val2.Stability;
						Data.monolith_stability_empower_slider.value = stability2;
						Data.monolith_stability_empower_text.text = stability2.ToString();
						if (!val2.SavedEchoWeb.IsNullOrDestroyed())
						{
							Data.monolith_corruption_go.active = true;
							int corruption = val2.SavedEchoWeb.Corruption;
							Data.monolith_corruption_slider.value = corruption;
							Data.monolith_corruption_text.text = corruption.ToString();
							Data.monolith_gaze_go.active = true;
							int gazeOfOrobyss = val2.SavedEchoWeb.GazeOfOrobyss;
							Data.monolith_gaze_slider.value = gazeOfOrobyss;
							Data.monolith_gaze_text.text = gazeOfOrobyss.ToString();
						}
						else
						{
							Data.monolith_corruption_go.active = false;
							int num3 = -1;
							Data.monolith_corruption_slider.value = num3;
							Data.monolith_corruption_text.text = num3.ToString();
							Data.monolith_gaze_go.active = false;
							int num4 = -1;
							Data.monolith_gaze_slider.value = num4;
							Data.monolith_gaze_text.text = num4.ToString();
						}
					}
					else
					{
						Data.monolith_stability_empower_go.active = false;
						int num5 = -1;
						Data.monolith_stability_empower_slider.value = num5;
						Data.monolith_stability_empower_text.text = num5.ToString();
					}
				}

				public static void Update_Faction_Data()
				{
					Faction_Tracker.factions_favor_text.text = Faction_Tracker.factions_favor_slider.value.ToString();
					Faction_Tracker.factions_rank_text.text = Faction_Tracker.factions_rank_slider.value.ToString();
					Faction_Tracker.factions_reputation_text.text = Faction_Tracker.factions_reputation_slider.value.ToString();
					if (Faction_Tracker.factions_dropdown.value > 0)
					{
						Faction_Tracker.factions_go.active = true;
					}
					else
					{
						Faction_Tracker.factions_go.active = false;
					}
					Faction_Tracker.selected_faction = Faction_Tracker.GetFaction();
				}

