				public static void Set_Active(bool show)
				{
					if (!content_obj.IsNullOrDestroyed())
					{
						content_obj.active = show;
						enable = show;
					}
				}

				public static void Toggle_Active()
				{
					if (!content_obj.IsNullOrDestroyed())
					{
						bool active = !content_obj.active;
						content_obj.active = active;
						enable = active;
					}
				}

