				public class Teleport
				{
					public static Dropdown scene_dropdown = null;

					public static Button scene_button = null;

					public static readonly Action Scene_OnClick_Action = Scene_Teleport;

					public static void Init()
					{
						//IL_0020: Unknown result type (might be due to invalid IL or missing references)
						//IL_002a: Expected O, but got Unknown
						//IL_01d9: Unknown result type (might be due to invalid IL or missing references)
						//IL_01e3: Expected O, but got Unknown
						scene_dropdown.options.Clear();
						scene_dropdown.options.Add(new OptionData("Select"));
						Teleport_ToScene.scene_names.Clear();
						Teleport_ToScene.scene_names.Add("");
						Enumerator<SceneDetails> enumerator = SceneList.instance.sceneDetailsCollection.GetEnumerator();
						while (enumerator.MoveNext())
						{
							SceneDetails current = enumerator.Current;
							if (current.Name != "PersistentUI" && current.Name != "CharacterSelectScene" && current.Name != "Login" && current.Name != "PersistentUI" && current.Name != "MonolithHub" && current.Name != "A_Reward" && current.Name != "Mastery" && current.Name != "Neutral" && current.Name != "PCG_Dev" && !current.Name.Contains("PCG") && !current.Name.Contains("Arena") && current.LocalizedName != current.Name && !Teleport_ToScene.scene_names.Contains(current.Name))
							{
								string text = "";
								text = ((!(current.Name != current.LocalizedName)) ? current.Name : (current.Name + " : " + current.LocalizedName));
								if (text != "")
								{
									Teleport_ToScene.scene_names.Add(current.Name);
									scene_dropdown.options.Add(new OptionData(text));
								}
							}
						}
					}

					public static void Scene_Teleport()
					{
						Teleport_ToScene.StartTp(scene_dropdown.value);
					}
				}

