				public static void Init_BeastDropdown()
				{
					//IL_0107: Unknown result type (might be due to invalid IL or missing references)
					//IL_0111: Expected O, but got Unknown
					TimeBeastData val = null;
					using (IEnumerator<TimeBeastData> enumerator = Resources.FindObjectsOfTypeAll<TimeBeastData>().GetEnumerator())
					{
						if (enumerator.MoveNext())
						{
							TimeBeastData current = enumerator.Current;
							val = current;
						}
					}
					if (!val.IsNullOrDestroyed())
					{
						List<string> list = new List<string>();
						Enumerator<AdaptationData> enumerator2 = val.adaptationData.GetEnumerator();
						while (enumerator2.MoveNext())
						{
							AdaptationData current2 = enumerator2.Current;
							list.Add(current2.displayName);
						}
						evo_count = list.Count;
						Dropdown[] array = (Dropdown[])(object)new Dropdown[7] { beast_evolution_0_select_dropdown, beast_evolution_1_select_dropdown, beast_evolution_2_select_dropdown, beast_evolution_3_select_dropdown, beast_evolution_4_select_dropdown, beast_evolution_5_select_dropdown, beast_evolution_6_select_dropdown };
						Dropdown[] array2 = array;
						foreach (Dropdown val2 in array2)
						{
							val2.options.Clear();
							foreach (string item in list)
							{
								val2.options.Add(new OptionData(item));
							}
						}
					}
					else
					{
						Main.logger_instance.Error("TimeBeastData not found");
					}
				}

