				public static void SelectType()
				{
					//IL_009b: Unknown result type (might be due to invalid IL or missing references)
					//IL_00a0: Unknown result type (might be due to invalid IL or missing references)
					if (Type_Initialized)
					{
						int value = type_dropdown.value;
						if (value < type_dropdown.options.Count)
						{
							string text = type_dropdown.options[type_dropdown.value].text;
							item_type = -1;
							bool flag = false;
							foreach (BaseEquipmentItem item in (Il2CppArrayBase<BaseEquipmentItem>)(object)ItemList.get().EquippableItems)
							{
								if (((BaseItem)item).BaseTypeName == text)
								{
									item_type = ((BaseItem)item).baseTypeID;
									item_equipmenttype = item.type;
									flag = true;
									break;
								}
							}
							if (!flag)
							{
								foreach (BaseNonEquipmentItem item2 in (Il2CppArrayBase<BaseNonEquipmentItem>)(object)ItemList.get().nonEquippableItems)
								{
									if (((BaseItem)item2).BaseTypeName == text)
									{
										item_type = ((BaseItem)item2).baseTypeID;
										flag = true;
										break;
									}
								}
							}
							if (!flag)
							{
								item_type = -1;
							}
							UpdateRarity();
							UpdateItems();
							shard_initialized = false;
						}
					}
					UpdateUI();
				}

