							});
						}
						if (flag2)
						{
							val.Add(new OptionData
							{
								text = "Set"
							});
						}
						((Behaviour)rarity_dropdown).enabled = true;
					}
					else
					{
						((Behaviour)rarity_dropdown).enabled = false;
