				public static void SelectRarity()
				{
					if (Type_Initialized)
					{
						int value = rarity_dropdown.value;
						if (value < rarity_dropdown.options.Count)
						{
							string text = rarity_dropdown.options[value].text;
							item_rarity = -1;
							switch (text)
							{
							case "Base Item":
								item_rarity = 0;
								break;
							case "Unique":
								item_rarity = 7;
								break;
							case "Set":
								item_rarity = 8;
								break;
							}
							UpdateItems();
						}
					}
					UpdateUI();
				}

				public static void UpdateItems()
				{
					//IL_004c: Unknown result type (might be due to invalid IL or missing references)
					//IL_0051: Unknown result type (might be due to invalid IL or missing references)
					//IL_0062: Expected O, but got Unknown
					//IL_0109: Unknown result type (might be due to invalid IL or missing references)
					//IL_010e: Unknown result type (might be due to invalid IL or missing references)
					//IL_011c: Expected O, but got Unknown
					//IL_01ce: Unknown result type (might be due to invalid IL or missing references)
					//IL_01d3: Unknown result type (might be due to invalid IL or missing references)
					//IL_01e1: Expected O, but got Unknown
					//IL_0305: Unknown result type (might be due to invalid IL or missing references)
					//IL_030a: Unknown result type (might be due to invalid IL or missing references)
					//IL_0318: Expected O, but got Unknown
					if (!enable || !LastEpoch_Hud.Scenes.IsGameScene() || Refs_Manager.item_list.IsNullOrDestroyed() || !Type_Initialized || items_dropdown.IsNullOrDestroyed())
					{
						return;
					}
					items_dropdown.ClearOptions();
					List<OptionData> val = new List<OptionData>();
					val.Add(new OptionData
					{
						text = "Select"
					});
					if (item_type > -1 && item_rarity > -1)
					{
						if (item_rarity == 0)
						{
							bool flag = false;
							foreach (BaseEquipmentItem item in (Il2CppArrayBase<BaseEquipmentItem>)(object)ItemList.get().EquippableItems)
							{
								if (((BaseItem)item).baseTypeID != item_type)
								{
									continue;
								}
								Enumerator<EquipmentItem> enumerator2 = item.subItems.GetEnumerator();
								while (enumerator2.MoveNext())
								{
									EquipmentItem current2 = enumerator2.Current;
									string text = ((SubItem)current2).displayName;
									if (text == "")
									{
										text = ((SubItem)current2).name;
									}
									val.Add(new OptionData
									{
										text = text
									});
								}
								flag = true;
							}
							if (!flag)
							{
								foreach (BaseNonEquipmentItem item2 in (Il2CppArrayBase<BaseNonEquipmentItem>)(object)ItemList.get().nonEquippableItems)
								{
									if (((BaseItem)item2).baseTypeID != item_type)
									{
										continue;
									}
									Enumerator<NonEquipmentItem> enumerator4 = item2.subItems.GetEnumerator();
									while (enumerator4.MoveNext())
									{
										NonEquipmentItem current4 = enumerator4.Current;
										string text2 = ((SubItem)current4).displayName;
										if (text2 == "")
										{
											text2 = ((SubItem)current4).name;
										}
										val.Add(new OptionData
										{
											text = text2
										});
									}
									flag = true;
								}
							}
						}
						else if (item_rarity == 7 || item_rarity == 8)
						{
							if (UniqueList.instance.IsNullOrDestroyed())
							{
								UniqueList.getUnique((ushort)0);
							}
							if (!UniqueList.instance.IsNullOrDestroyed())
							{
								Enumerator<Entry> enumerator5 = UniqueList.instance.uniques.GetEnumerator();
								while (enumerator5.MoveNext())
								{
									Entry current5 = enumerator5.Current;
									if (current5.baseType == item_type && ((item_rarity == 7 && !current5.isSetItem) || (item_rarity == 8 && current5.isSetItem)))
									{
										string text3 = current5.displayName;
										if (text3 == "" || text3 == "Pearls of the Swine" || text3 == "Scales of Eterra")
										{
											text3 = current5.name;
										}
										val.Add(new OptionData
										{
											text = text3
										});
									}
								}
							}
						}
						((Behaviour)items_dropdown).enabled = true;
					}
					else
					{
						((Behaviour)items_dropdown).enabled = false;
					}
					items_dropdown.options = val;
					items_dropdown.value = 0;
				}

