					string text = items_dropdown.options[items_dropdown.value].text;
					item_subtype = -1;
					item_unique_id = 0;
					bool flag = false;
					if (item_rarity == 0)
					{
						foreach (BaseEquipmentItem item in (Il2CppArrayBase<BaseEquipmentItem>)(object)ItemList.get().EquippableItems)
						{
							if (((BaseItem)item).baseTypeID != item_type)
							{
								continue;
							}
							Enumerator<EquipmentItem> enumerator2 = item.subItems.GetEnumerator();
							while (enumerator2.MoveNext())
							{
								EquipmentItem current2 = enumerator2.Current;
								if (text == ((SubItem)current2).displayName || text == ((SubItem)current2).name)
								{
									item_subtype = ((SubItem)current2).subTypeID;
									flag = true;
									break;
								}
							}
						}
						if (!flag)
						{
							foreach (BaseNonEquipmentItem item2 in (Il2CppArrayBase<BaseNonEquipmentItem>)(object)ItemList.get().nonEquippableItems)
							{
								if (((BaseItem)item2).baseTypeID != item_type)
								{
									continue;
								}
								Enumerator<NonEquipmentItem> enumerator4 = item2.subItems.GetEnumerator();
								while (enumerator4.MoveNext())
								{
									NonEquipmentItem current4 = enumerator4.Current;
									if (text == ((SubItem)current4).displayName || text == ((SubItem)current4).name)
									{
										item_subtype = ((SubItem)current4).subTypeID;
										break;
									}
								}
							}
						}
					}
					else if (item_rarity == 7 || item_rarity == 8)
					{
						if (UniqueList.instance.IsNullOrDestroyed())
						{
							UniqueList.getUnique((ushort)0);
						}
						if (!UniqueList.instance.IsNullOrDestroyed())
						{
							Enumerator<Entry> enumerator5 = UniqueList.instance.uniques.GetEnumerator();
							while (enumerator5.MoveNext())
							{
								Entry current5 = enumerator5.Current;
								if (text == current5.displayName || text == current5.name)
								{
									item_subtype = current5.subTypes[0];
									item_unique_id = current5.uniqueID;
									item_legendary_type = current5.legendaryType;
									break;
								}
							}
						}
					}
					UpdateUI();
				}

