				public static void Init_Dropdowns()
				{
					GetLegendaryType(Headhunter_LegendaryType_dropdown);
					GetAbility(Mjolnir_Socket0_dropdown, "", mjolnir: true, herald: false);
					GetAbility(Mjolnir_Socket1_dropdown, "", mjolnir: true, herald: false);
					GetAbility(Mjolnir_Socket2_dropdown, "", mjolnir: true, herald: false);
					GetLegendaryType(Mjolnir_LegendaryType_dropdown);
					GetAbility(Herald_of_Ice_VFX_dropdown, "Cold, Spell", mjolnir: false, herald: true);
					GetLegendaryType(Herald_of_Ice_LegendaryType_dropdown);
					GetAbility(Herald_of_Fire_VFX_dropdown, "Fire, Spell", mjolnir: false, herald: true);
					GetLegendaryType(Herald_of_Fire_LegendaryType_dropdown);
					GetAbility(Herald_of_Thunder_VFX_dropdown, "Lightning, Spell", mjolnir: false, herald: true);
					GetLegendaryType(Herald_of_Thunder_LegendaryType_dropdown);
					GetAbility(Herald_of_Agony_VFX_dropdown, "Poison, Spell", mjolnir: false, herald: true);
					GetLegendaryType(Herald_of_Agony_LegendaryType_dropdown);
					GetAbility(Herald_of_Purity_VFX_dropdown, "Physical, Spell", mjolnir: false, herald: true);
					GetLegendaryType(Herald_of_Agony_LegendaryType_dropdown);
				}

				public static void GetLegendaryType(Dropdown dropdown)
				{
					//IL_0022: Unknown result type (might be due to invalid IL or missing references)
					//IL_0030: Unknown result type (might be due to invalid IL or missing references)
					//IL_003a: Expected O, but got Unknown
					//IL_0042: Unknown result type (might be due to invalid IL or missing references)
					//IL_0050: Unknown result type (might be due to invalid IL or missing references)
					//IL_005a: Expected O, but got Unknown
					if (!dropdown.IsNullOrDestroyed())
					{
						dropdown.options.Clear();
						dropdown.options.Add(new OptionData(((object)(LegendaryType)0/*cast due to .constrained prefix*/).ToString()));
						dropdown.options.Add(new OptionData(((object)(LegendaryType)1/*cast due to .constrained prefix*/).ToString()));
					}
				}

				public static void GetAbility(Dropdown dropdown, string tags, bool mjolnir, bool herald)
				{
					//IL_0041: Unknown result type (might be due to invalid IL or missing references)
					//IL_0059: Unknown result type (might be due to invalid IL or missing references)
					//IL_00aa: Unknown result type (might be due to invalid IL or missing references)
					//IL_00af: Unknown result type (might be due to invalid IL or missing references)
					//IL_01a0: Unknown result type (might be due to invalid IL or missing references)
					//IL_01aa: Expected O, but got Unknown
					if (dropdown.IsNullOrDestroyed())
					{
						return;
					}
					dropdown.options.Clear();
					List<string> list = new List<string>();
					foreach (Ability item in Resources.FindObjectsOfTypeAll<Ability>())
					{
						if (mjolnir && ((Enum)item.tags).HasFlag((Enum)(object)(AT)2) && ((Enum)item.tags).HasFlag((Enum)(object)(AT)256))
						{
							if (!list.Contains(item.abilityName))
							{
								list.Add(item.abilityName);
							}
						}
						else if (herald && ((object)item.tags/*cast due to .constrained prefix*/).ToString() == tags && !item.abilityPrefab.IsNullOrDestroyed())
						{
							bool flag = false;
							SphereCollider component = item.abilityPrefab.GetComponent<SphereCollider>();
							if (!component.IsNullOrDestroyed())
							{
								flag = true;
							}
							bool flag2 = false;
							CreateVfxOnDeath component2 = item.abilityPrefab.GetComponent<CreateVfxOnDeath>();
							if (!component2.IsNullOrDestroyed())
							{
								flag2 = true;
							}
							if (flag && flag2 && !list.Contains(((Object)item).name))
							{
								list.Add(((Object)item).name);
							}
						}
					}
					list.Sort();
					foreach (string item2 in list)
					{
						dropdown.options.Add(new OptionData(item2));
					}
				}

				public static void Set_Events()
				{
					if (!Headhunter_MinGeneratedBuff_slider.IsNullOrDestroyed())
					{
						Events.Set_Slider_Event(Headhunter_MinGeneratedBuff_slider, UnityAction<float>.op_Implicit(Headhunter_MinGeneratedBuff_slider_Action));
					}
					if (!Headhunter_MaxGeneratedBuff_slider.IsNullOrDestroyed())
					{
