			public static GameObject content_obj;

			public static void Set_Active()
			{
				if (!content_obj.IsNullOrDestroyed())
				{
					bool flag = false;
					if (Character.enable || Items.enable || Scenes.enable || Skills.enable || OdlForceDrop.enable || NewItems.enable || Maxroll.enable)
					{
						flag = true;
					}
					if (content_obj.active != flag)
					{
						content_obj.active = flag;
					}
				}
			}

			public static void Close_AllContent()
			{
				Character.enable = false;
				Items.enable = false;
				Scenes.enable = false;
				Skills.enable = false;
				OdlForceDrop.enable = false;
				NewItems.enable = false;
				Maxroll.enable = false;
			}
		}

		public static Hud_Manager instance;

		public static AssetBundle asset_bundle;

		public static GameObject hud_object;

		public bool data_initialized = false;

		private string asset_path = Application.dataPath + "/../Mods/LastEpoch_Hud/Assets";

		private static Canvas game_canvas;

		public static GameObject game_pause_menu;

		private static Canvas hud_canvas;

		private readonly string asset_bundle_name = "lastepochmods";

		private bool hud_initializing = false;

		private bool data_initializing = false;

		private bool updating = false;

		public static bool enable;

		private bool exit = false;

		private void Awake()
		{
			instance = this;
			enable = true;
			AssetBundleCreateRequest val = AssetBundle.LoadFromFileAsync(Path.Combine(asset_path, asset_bundle_name));
			asset_bundle = val.assetBundle;
			if ((Object)(object)asset_bundle == (Object)null)
			{
				Main.logger_instance.Error("AssetBundle Error");
			}
			else
			{
				Object.DontDestroyOnLoad((Object)(object)asset_bundle);
			}
		}

		private void Update()
		{
			if (asset_bundle.IsNullOrDestroyed())
			{
				return;
			}
			Update_Hud_Scale();
			Update_Refs();
			Update_Locale();
			if (hud_object.IsNullOrDestroyed())
			{
				return;
			}
			if (!data_initialized && !data_initializing)
			{
				Init_UserData();
			}
			if (IsPauseOpen() && !updating)
			{
				updating = true;
				Update_Hud_Content();
				hud_object.active = true;
				Content.Set_Active();
				if (!Refs_Manager.epoch_input_manager.IsNullOrDestroyed() && !Refs_Manager.epoch_input_manager.forceDisableInput)
				{
					Refs_Manager.epoch_input_manager.forceDisableInput = true;
				}
				if (Input.GetKeyDown((KeyCode)27))
				{
					exit = true;
				}
				if (!Hud_Base.Btn_Resume.IsNullOrDestroyed() && Input.GetKeyUp((KeyCode)27) && exit)
				{
					((UnityEvent)Hud_Base.Btn_Resume.onClick).Invoke();
					exit = false;
				}
				updating = false;
			}
			else if (!updating)
			{
				updating = true;
				if (hud_object.active)
				{
					hud_object.active = false;
				}
				if (!Refs_Manager.epoch_input_manager.IsNullOrDestroyed() && Refs_Manager.epoch_input_manager.forceDisableInput)
				{
					Refs_Manager.epoch_input_manager.forceDisableInput = false;
				}
				Content.Character.need_update = true;
				updating = false;
			}
		}

		private void Init_Hud()
		{
			//IL_0136: Unknown result type (might be due to invalid IL or missing references)
			//IL_013b: Unknown result type (might be due to invalid IL or missing references)
			//IL_032d: Unknown result type (might be due to invalid IL or missing references)
			//IL_0332: Unknown result type (might be due to invalid IL or missing references)
			hud_initializing = true;
			if (Main.debug)
			{
				Main.logger_instance.Msg("Hud Manager : Load hud object in assets");
			}
			if (!asset_bundle.IsNullOrDestroyed())
			{
				string text = "";
				foreach (string item in (Il2CppArrayBase<string>)(object)asset_bundle.GetAllAssetNames())
				{
					if (Functions.Check_Prefab(item) && item.Contains("/hud/") && item.Contains("hud.prefab"))
					{
						if (Main.debug)
						{
							Main.logger_instance.Msg("Hud Manager : Hud prefab found");
						}
						text = item;
						break;
					}
				}
				if (text != "")
				{
					Object val = asset_bundle.LoadAsset(text);
					GameObject val2 = ((Il2CppObjectBase)val).TryCast<GameObject>();
					if (!val2.IsNullOrDestroyed())
					{
						val2.active = false;
						val2.AddComponent<UIMouseListener>();
						val2.AddComponent<WindowFocusManager>();
						if (Main.debug)
						{
							Main.logger_instance.Msg("Hud Manager : Instantiate hud prefab");
						}
						hud_object = Object.Instantiate<GameObject>(val2, Vector3.zero, Quaternion.identity);
						Object.DontDestroyOnLoad((Object)(object)hud_object);
						if (Main.debug)
						{
							Main.logger_instance.Msg("Hud Manager : Initialize hud refs");
						}
						Hud_Menu.Set_Events();
						Content.content_obj = Functions.GetChild(hud_object, "Content");
						Content.Character.Get_Refs();
						Content.Character.Set_Events();
						Content.Character.Set_Active(show: false);
						Content.Items.Get_Refs();
						Content.Items.Set_Events();
						Content.Items.Set_Active(show: false);
						Content.Scenes.Get_Refs();
						Content.Scenes.Set_Events();
						Content.Scenes.Set_Active(show: false);
						Content.Skills.Get_Refs();
						Content.Skills.Set_Events();
						Content.Skills.Set_Active(show: false);
						Content.OdlForceDrop.Get_Refs();
						Content.OdlForceDrop.Init_BeastDropdown();
						Content.OdlForceDrop.Set_Events();
						Content.OdlForceDrop.Set_Active(show: false);
						Content.NewItems.Get_Refs();
						Content.NewItems.Init_Dropdowns();
						Content.NewItems.Set_Events();
						Content.NewItems.Set_Active(show: false);
						Content.Maxroll.Get_Refs();
						Content.Maxroll.Set_Events();
						Content.Maxroll.Set_Active(show: false);
						try
						{
							SaveManager.BindHud(hud_object);
						}
						catch (Exception ex)
						{
							Instance logger_instance = Main.logger_instance;
							if (logger_instance != null)
							{
								logger_instance.Error("ModUI BindHud failed: " + ex.Message);
							}
						}
					}
					else
					{
						Main.logger_instance.Error("Hud Manager : Hud Prefab not found");
					}
				}
				text = "";
				foreach (string item2 in (Il2CppArrayBase<string>)(object)asset_bundle.GetAllAssetNames())
				{
					if (Functions.Check_Prefab(item2) && item2.Contains("/hud/") && item2.Contains("mod_shard.prefab"))
					{
						text = item2;
						break;
					}
				}
				if (text != "")
				{
					GameObject val3 = ((Il2CppObjectBase)asset_bundle.LoadAsset(text)).TryCast<GameObject>();
					if (!val3.IsNullOrDestroyed())
					{
						if (Main.debug)
						{
							Main.logger_instance.Msg("Hud Manager : Instantiate shard prefab");
						}
						Content.OdlForceDrop.shard_prefab = Object.Instantiate<GameObject>(val3, Vector3.zero, Quaternion.identity);
						Object.DontDestroyOnLoad((Object)(object)Content.OdlForceDrop.shard_prefab);
					}
					else
					{
						Main.logger_instance.Error("Hud Manager : Shard Prefab not found");
					}
				}
				else
				{
					Main.logger_instance.Error("Hud Manager : Shard Prefab name not found");
				}
			}
			hud_initializing = false;
		}

		private void Init_UserData()
		{
			data_initializing = true;
			if (!Save_Manager.instance.IsNullOrDestroyed())
			{
				if (Main.debug)
				{
					Main.logger_instance.Msg("Hud Manager : Initialize user config");
				}
				bool flag = Content.Character.Init_UserData();
				bool flag2 = Content.Items.Init_UserData();
				bool flag3 = Content.Scenes.Init_UserData();
				bool flag4 = Content.Skills.Init_UserData();
				bool flag5 = Content.NewItems.Init_Data();
				if (flag && flag2 && flag3 && flag4 && flag5)
				{
					if (Main.debug)
					{
						Main.logger_instance.Msg("Hud Manager : Initialized");
					}
					data_initialized = true;
				}
			}
			data_initializing = false;
		}

		private void Update_Refs()
		{
			if (hud_canvas.IsNullOrDestroyed() && !hud_object.IsNullOrDestroyed())
			{
				hud_canvas = hud_object.GetComponent<Canvas>();
			}
			if (!Refs_Manager.game_uibase.IsNullOrDestroyed())
			{
				if (game_canvas.IsNullOrDestroyed() && Refs_Manager.game_uibase.canvases.Count > 0)
				{
					game_canvas = Refs_Manager.game_uibase.canvases[0];
				}
				if (Scenes.IsGameScene() && (game_pause_menu.IsNullOrDestroyed() || Hud_Base.Default_PauseMenu_Btns.IsNullOrDestroyed()))
				{
					Hud_Base.Get_DefaultPauseMenu();
				}
				if (!Hud_Base.initiliazed_events && !game_pause_menu.IsNullOrDestroyed() && !Hud_Base.Default_PauseMenu_Btns.IsNullOrDestroyed())
				{
					Hud_Base.Set_Events();
				}
				if (Hud_Base.Get_DefaultPauseMenu_Open())
				{
					Hud_Base.Toogle_DefaultPauseMenu(show: false);
				}
			}
			if (!asset_bundle.IsNullOrDestroyed() && hud_object.IsNullOrDestroyed() && !hud_initializing)
			{
				Init_Hud();
			}
		}

		private void Update_Hud_Scale()
		{
			if (!Refs_Manager.game_uibase.IsNullOrDestroyed() && !game_canvas.IsNullOrDestroyed() && !hud_canvas.IsNullOrDestroyed() && hud_canvas.scaleFactor != game_canvas.scaleFactor)
			{
				hud_canvas.scaleFactor = game_canvas.scaleFactor;
			}
		}

		private void Update_Locale()
		{
			if (!Locales.update || hud_object.IsNullOrDestroyed())
			{
				return;
			}
			Locales.update = false;
			foreach (GameObject item in Functions.GetAllChild(hud_object))
			{
				foreach (GameObject item2 in Functions.GetAllChild(item))
				{
					ReplaceText(item2);
					foreach (GameObject item3 in Functions.GetAllChild(item2))
					{
						ReplaceText(item3);
						foreach (GameObject item4 in Functions.GetAllChild(item3))
						{
							ReplaceText(item4);
							foreach (GameObject item5 in Functions.GetAllChild(item4))
							{
								ReplaceText(item5);
								foreach (GameObject item6 in Functions.GetAllChild(item5))
								{
									ReplaceText(item6);
									foreach (GameObject item7 in Functions.GetAllChild(item6))
									{
										ReplaceText(item7);
										foreach (GameObject item8 in Functions.GetAllChild(item7))
										{
											ReplaceText(item8);
											foreach (GameObject item9 in Functions.GetAllChild(item8))
											{
												ReplaceText(item9);
											}
										}
									}
								}
							}
						}
					}
				}
			}
		}

		private void ReplaceText(GameObject go)
		{
			try
			{
				Text component = go.GetComponent<Text>();
				if (component.IsNullOrDestroyed())
				{
					return;
				}
				bool flag = false;
				string text = component.text;
				foreach (char value in text)
				{
					if (Enumerable.Contains(Locales.igrone_str, value))
					{
						flag = true;
						break;
					}
				}
				if (!flag && Locales.current_dictionary != null && Locales.current_dictionary.ContainsKey(component.text))
				{
					component.text = Locales.current_dictionary[component.text];
				}
			}
			catch
			{
			}
		}

