		public string path = Directory.GetCurrentDirectory() + "\\Mods\\LastEpoch_Hud\\";

		private string filename = "Save.json";

		public Data.Mods_Structure data = default(Data.Mods_Structure);

		public Data.Mods_Structure data_duplicate = default(Data.Mods_Structure);

		public bool initialized = false;

		public static Save_Manager instance { get; private set; }

		private void Awake()
		{
			instance = this;
		}

		private async void Start()
		{
			await Task.Run(delegate
			{
				Load();
			});
		}

		private void Update()
		{
			if (initialized)
			{
				Check_DataChanged();
			}
		}

		private void Load()
		{
			bool flag = false;
			if (File.Exists(path + filename))
			{
				Instance logger_instance = Main.logger_instance;
				if (logger_instance != null)
				{
					logger_instance.Msg("Save Manager : Loading file : " + path + filename);
				}
				try
				{
					data = JsonConvert.DeserializeObject<Data.Mods_Structure>(File.ReadAllText(path + filename));
				}
				catch
				{
					Instance logger_instance2 = Main.logger_instance;
					if (logger_instance2 != null)
					{
						logger_instance2.Warning("Save Manager : Error when deserializing the file");
					}
					flag = true;
				}
			}
			else
			{
				flag = true;
			}
			if (flag)
			{
				Main.logger_instance.Msg("Save Manager : Generate default config");
				data = Get_DefaultConfig();
				Save();
			}
			Check_Update();
			data_duplicate = data;
			Main.logger_instance.Msg("Save Manager : Data initialized");
			initialized = true;
		}

