		private void Check_Update()
		{
			bool flag = false;
			if (data.ModVersion != "4.4.7")
			{
				data.ModVersion = "4.4.7";
				flag = true;
			}
			if (flag)
			{
				Save();
			}
		}

		private void Check_DataChanged()
		{
			if (!data.Equals(data_duplicate))
			{
				data_duplicate = data;
				Save();
				if (!Mods_Manager.instance.IsNullOrDestroyed())
				{
					Mods_Manager.instance.change = true;
				}
			}
		}

		public void Save()
		{
			string contents = JsonConvert.SerializeObject((object)data, (Formatting)1);
			if (!Directory.Exists(path))
			{
				Directory.CreateDirectory(path);
			}
			if (File.Exists(path + filename))
			{
				File.Delete(path + filename);
			}
			File.WriteAllText(path + filename, contents);
		}
	}
