namespace LastEpoch_Hud.Scripts.ModUI
{
	public enum RootKind
	{
		Generic,
		HudWithTabs
	}
	internal static class BindingRoots
	{
		internal struct Entry
		{
			public GameObject Root;

			public RootKind Kind;
		}

		public const string HudRootName = "Hud";

		private static readonly Dictionary<string, Entry> roots = new Dictionary<string, Entry>();

		public static IEnumerable<string> AllNames => roots.Keys;

		public static void Register(string name, GameObject root, RootKind kind)
		{
			if (!string.IsNullOrEmpty(name) && !((Object)(object)root == (Object)null))
			{
				roots[name] = new Entry
				{
					Root = root,
					Kind = kind
				};
			}
		}

		public static bool TryGet(string name, out GameObject root, out RootKind kind)
		{
			if (roots.TryGetValue(name, out var value) && (Object)(object)value.Root != (Object)null && !value.Root.IsNullOrDestroyed())
			{
				root = value.Root;
				kind = value.Kind;
				return true;
			}
			root = null;
			kind = RootKind.Generic;
			return false;
		}

		public static bool IsSameRoot(string name, GameObject root)
		{
			Entry value;
			return roots.TryGetValue(name, out value) && value.Root == root;
		}

		public static void Unregister(string name)
		{
			roots.Remove(name);
		}
	}
	internal static class LocaleRegistry
	{
		private static readonly List<(Text Text, string EnglishLabel)> entries = new List<(Text, string)>();

		private static Dictionary<string, string> lastDict;

		public static void Register(Text text, string englishLabel)
		{
			if ((Object)(object)text == (Object)null || string.IsNullOrEmpty(englishLabel))
			{
				return;
			}
			for (int i = 0; i < entries.Count; i++)
			{
				if ((Object)(object)entries[i].Text == (Object)(object)text)
				{
					entries[i] = (text, englishLabel);
					return;
				}
			}
			entries.Add((text, englishLabel));
		}

		public static void TickIfLocaleChanged()
		{
			Dictionary<string, string> current_dictionary = Locales.current_dictionary;
			if (current_dictionary != lastDict)
			{
				lastDict = current_dictionary;
				ReapplyAll();
			}
		}

		public static void SweepDead()
		{
			for (int num = entries.Count - 1; num >= 0; num--)
			{
				Text item = entries[num].Text;
				if ((Object)(object)item == (Object)null || item.IsNullOrDestroyed())
				{
					entries.RemoveAt(num);
				}
			}
		}

		private static void ReapplyAll()
		{
			for (int num = entries.Count - 1; num >= 0; num--)
			{
				(Text, string) tuple = entries[num];
				if ((Object)(object)tuple.Item1 == (Object)null || tuple.Item1.IsNullOrDestroyed())
				{
					entries.RemoveAt(num);
				}
				else
				{
					Prefab.ApplyLabel(tuple.Item1, tuple.Item2);
				}
			}
		}
	}
	public static class Prefab
	{
		public static GameObject Child(GameObject parent, string name)
		{
			if ((Object)(object)parent == (Object)null)
			{
				return null;
			}
			for (int i = 0; i < parent.transform.childCount; i++)
			{
				GameObject gameObject = ((Component)parent.transform.GetChild(i)).gameObject;
				if (((Object)gameObject).name == name)
				{
					return gameObject;
				}
			}
			return null;
		}

		public static T Component<T>(GameObject parent, string panelName, string childName) where T : Component
		{
			GameObject val = Child(parent, panelName);
			if ((Object)(object)val == (Object)null)
			{
				return default(T);
			}
			GameObject val2 = Child(val, childName);
			if ((Object)(object)val2 == (Object)null)
			{
				return default(T);
			}
			return val2.GetComponent<T>();
		}

		public static GameObject ChildPath(GameObject parent, string path)
		{
			if ((Object)(object)parent == (Object)null || string.IsNullOrEmpty(path))
			{
				return null;
			}
			GameObject val = parent;
			string[] array = path.Split('/');
			foreach (string text in array)
			{
				if (!string.IsNullOrEmpty(text))
				{
					val = Child(val, text);
					if ((Object)(object)val == (Object)null)
					{
						return null;
					}
				}
			}
			return val;
		}

		public static T ComponentAtPath<T>(GameObject parent, string path) where T : Component
		{
			GameObject val = ChildPath(parent, path);
			return ((Object)(object)val == (Object)null) ? default(T) : val.GetComponent<T>();
		}

		public static GameObject ViewportContent(GameObject parent, string panelName, string contentName)
		{
			GameObject val = Child(parent, panelName);
			if ((Object)(object)val == (Object)null)
			{
				return null;
			}
			GameObject val2 = Child(val, contentName);
			if ((Object)(object)val2 == (Object)null)
			{
				return null;
			}
			GameObject val3 = Child(val2, "Viewport");
			if ((Object)(object)val3 == (Object)null)
			{
				return null;
			}
			return Child(val3, "Content");
		}

		public static Text FindText(GameObject parent, string panelName, string toggleName)
		{
			GameObject val = Child(parent, panelName);
			if ((Object)(object)val == (Object)null)
			{
				return null;
			}
			GameObject val2 = Child(val, toggleName);
			if ((Object)(object)val2 != (Object)null)
			{
				GameObject val3 = Child(val2, "Value");
				if ((Object)(object)val3 != (Object)null)
				{
					return val3.GetComponent<Text>();
				}
				val3 = Child(val2, "Label");
				if ((Object)(object)val3 != (Object)null)
				{
					return val3.GetComponent<Text>();
				}
			}
			GameObject val4 = Child(val, "Value");
			return ((Object)(object)val4 != (Object)null) ? val4.GetComponent<Text>() : null;
		}

		public static Text FindLabel(GameObject parent, string panelName, string toggleName)
		{
			GameObject val = Child(parent, panelName);
			if ((Object)(object)val == (Object)null)
			{
				return null;
			}
			GameObject val2 = Child(val, toggleName);
			if ((Object)(object)val2 == (Object)null)
			{
				return null;
			}
			GameObject val3 = Child(val2, "Label");
			return ((Object)(object)val3 != (Object)null) ? val3.GetComponent<Text>() : null;
		}

		public static void ApplyLabel(Text text, string englishLabel)
		{
			if (!((Object)(object)text == (Object)null) && !string.IsNullOrEmpty(englishLabel))
			{
				LocaleRegistry.Register(text, englishLabel);
				Dictionary<string, string> current_dictionary = Locales.current_dictionary;
				if (current_dictionary != null && current_dictionary.TryGetValue(englishLabel, out var value) && !string.IsNullOrEmpty(value))
				{
					text.text = value;
				}
				else
				{
					text.text = englishLabel;
				}
			}
		}

		public static Toggle ToggleInTitle(GameObject parent, string panelName, string toggleName, bool activate = false)
		{
			GameObject val = Child(parent, panelName);
			if ((Object)(object)val == (Object)null)
			{
				return null;
			}
			GameObject val2 = Child(val, "Title");
			if ((Object)(object)val2 == (Object)null)
			{
				return null;
			}
			GameObject val3 = Child(val2, toggleName);
			if ((Object)(object)val3 == (Object)null)
			{
				return null;
			}
			if (activate)
			{
				val3.SetActive(true);
			}
			return val3.GetComponent<Toggle>();
		}

		public static void BindButton(Button btn, UnityAction action)
		{
			((UnityEvent)btn.onClick).AddListener(action);
		}

		public static void BindToggle(Toggle toggle, UnityAction<bool> action)
		{
			((UnityEvent<bool>)(object)toggle.onValueChanged).AddListener(action);
		}

		public static void BindDropdown(Dropdown dropdown, UnityAction<int> action)
		{
			((UnityEvent<int>)(object)dropdown.onValueChanged).AddListener(action);
		}

		public static void ForEachDescendant(GameObject root, Action<GameObject> visitor)
		{
			for (int i = 0; i < root.transform.childCount; i++)
			{
				GameObject gameObject = ((Component)root.transform.GetChild(i)).gameObject;
				visitor(gameObject);
				ForEachDescendant(gameObject, visitor);
			}
		}

		public static void ReplaceAllText(GameObject root)
		{
			if (Locales.current_dictionary == null)
			{
				return;
			}
			ForEachDescendant(root, delegate(GameObject go)
			{
				Text component = go.GetComponent<Text>();
				if (!((Object)(object)component == (Object)null) && component.text.Length != 0 && Array.IndexOf(Locales.igrone_str, component.text[0]) < 0 && Locales.current_dictionary.ContainsKey(component.text))
				{
					component.text = Locales.current_dictionary[component.text];
				}
			});
		}
	}
	[RegisterTypeInIl2Cpp]
	public class SaveManager : MonoBehaviour
	{
		public static SaveManager instance;

		public volatile bool initialized;

		private static readonly string basePath = Directory.GetCurrentDirectory() + "\\Mods\\LastEpoch_Hud\\";

		private const string filename = "SaveModUI.json";

		private const float SaveInterval = 1f;

		private float saveTimer;

		public SaveManager(IntPtr ptr)
			: base(ptr)
		{
		}

		private void Awake()
		{
			instance = this;
		}

		private void Start()
		{
			Task.Run(delegate
			{
				try
				{
					Load();
				}
				catch (Exception ex)
				{
					Instance logger_instance = Main.logger_instance;
					if (logger_instance != null)
					{
						logger_instance.Error("ModUI SaveManager: Load failed: " + ex.Message);
					}
				}
			});
		}

		private void Update()
		{
			LocaleRegistry.TickIfLocaleChanged();
			if (KeybindCapture.Active)
			{
				KeybindCapture.Tick();
			}
			if (initialized && ModSettings.Dirty)
			{
				saveTimer += Time.unscaledDeltaTime;
				if (!(saveTimer < 1f))
				{
					saveTimer = 0f;
					ModSettings.ClearDirty();
					ModSettings.Trace("SaveManager.Update flushing (debounce hit)");
					Save();
				}
			}
		}

		private void Load()
		{
			string text = basePath + "SaveModUI.json";
			bool flag = false;
			if (File.Exists(text))
			{
				Instance logger_instance = Main.logger_instance;
				if (logger_instance != null)
				{
					logger_instance.Msg("ModUI SaveManager: Loading " + text);
				}
				try
				{
					JObject val = JObject.Parse(File.ReadAllText(text));
					foreach (SettingsGroup allGroup in ModSettings.AllGroups)
					{
						allGroup.Load(val);
					}
					foreach (SettingsGroup allGroup2 in ModSettings.AllGroups)
					{
						if (val[allGroup2.Name] == null)
						{
							flag = true;
							break;
						}
					}
				}
				catch
				{
					Instance logger_instance2 = Main.logger_instance;
					if (logger_instance2 != null)
					{
						logger_instance2.Warning("ModUI SaveManager: Error parsing save file, using defaults");
					}
					flag = true;
				}
			}
			else
			{
				Instance logger_instance3 = Main.logger_instance;
				if (logger_instance3 != null)
				{
					logger_instance3.Msg("ModUI SaveManager: No save file found, using defaults");
				}
				flag = true;
			}
			Instance logger_instance4 = Main.logger_instance;
			if (logger_instance4 != null)
			{
				logger_instance4.Msg("ModUI SaveManager: Initialized with " + ModSettings.AllGroups.Count + " group(s)");
			}
			initialized = true;
			if (flag)
			{
				Save();
				Instance logger_instance5 = Main.logger_instance;
				if (logger_instance5 != null)
				{
					logger_instance5.Msg("ModUI SaveManager: Wrote fresh schema to SaveModUI.json");
				}
			}
		}

		private void Save()
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_0007: Expected O, but got Unknown
			JObject val = new JObject();
			foreach (SettingsGroup allGroup in ModSettings.AllGroups)
			{
				allGroup.Save(val);
			}
			if (!Directory.Exists(basePath))
			{
				Directory.CreateDirectory(basePath);
			}
			File.WriteAllText(basePath + "SaveModUI.json", ((JToken)val).ToString((Formatting)1, Array.Empty<JsonConverter>()));
			ModSettings.Trace("SaveManager.Save wrote SaveModUI.json");
		}

		public static void BindHud(GameObject hud_object)
		{
			BindRoot("Hud", hud_object, RootKind.HudWithTabs);
		}

		public static void BindRoot(string name, GameObject root, RootKind kind = RootKind.Generic)
		{
			if ((Object)(object)instance == (Object)null || root.IsNullOrDestroyed() || string.IsNullOrEmpty(name))
			{
				return;
			}
			if (BindingRoots.IsSameRoot(name, root))
			{
				Instance logger_instance = Main.logger_instance;
				if (logger_instance != null)
				{
					logger_instance.Msg("ModUI SaveManager: BindRoot " + name + " skipped (same root already bound)");
				}
				return;
			}
			LocaleRegistry.SweepDead();
			BindingRoots.Register(name, root, kind);
			if (kind == RootKind.HudWithTabs)
			{
				BindHudInternal(root);
			}
			else
			{
				BindGenericRoot(name, root);
			}
			Instance logger_instance2 = Main.logger_instance;
			if (logger_instance2 != null)
			{
				logger_instance2.Msg("ModUI SaveManager: BindRoot " + name + " (kind=" + kind.ToString() + ", groups=" + ModSettings.AllGroups.Count + ")");
			}
		}

		private static void BindHudInternal(GameObject hud_object)
		{
			GameObject child = Functions.GetChild(hud_object, "Content");
			GameObject child2 = Functions.GetChild(hud_object, "Menu");
			GameObject val = (child2.IsNullOrDestroyed() ? null : Functions.GetChild(child2, "Content"));
			if (child.IsNullOrDestroyed() || val.IsNullOrDestroyed())
			{
				Instance logger_instance = Main.logger_instance;
				if (logger_instance != null)
				{
					logger_instance.Warning("ModUI SaveManager: BindHudInternal couldn't resolve Content or Menu/Content");
				}
			}
			else
			{
				TabManager.Init(child, val);
				BindNonTabGroups(child);
			}
		}

		private static void BindNonTabGroups(GameObject contentRoot)
		{
			foreach (SettingsGroup allGroup in ModSettings.AllGroups)
			{
				if (allGroup.RootName != "Hud" || allGroup.HasTab || allGroup.ContentObjectName == null)
				{
					continue;
				}
				try
				{
					GameObject val = Prefab.Child(contentRoot, allGroup.ContentObjectName);
					if ((Object)(object)val != (Object)null)
					{
						allGroup.ResolveAndBind(val);
					}
				}
				catch (Exception ex)
				{
					Instance logger_instance = Main.logger_instance;
					if (logger_instance != null)
					{
						logger_instance.Error("ModUI SaveManager: Failed to bind group '" + allGroup.Name + "': " + ex.Message);
					}
				}
			}
		}

		private static void BindGenericRoot(string rootName, GameObject root)
		{
			foreach (SettingsGroup allGroup in ModSettings.AllGroups)
			{
				if (allGroup.RootName != rootName)
				{
					continue;
				}
				try
				{
					GameObject val = ((allGroup.ContentObjectName != null) ? Prefab.Child(root, allGroup.ContentObjectName) : root);
					if ((Object)(object)val != (Object)null)
					{
						allGroup.ResolveAndBind(val);
						continue;
					}
					Instance logger_instance = Main.logger_instance;
					if (logger_instance != null)
					{
						logger_instance.Warning("ModUI SaveManager: BindGenericRoot '" + rootName + "' missing content '" + allGroup.ContentObjectName + "' for group '" + allGroup.Name + "'");
					}
				}
				catch (Exception ex)
				{
					Instance logger_instance2 = Main.logger_instance;
					if (logger_instance2 != null)
					{
						logger_instance2.Error("ModUI SaveManager: Failed to bind group '" + allGroup.Name + "' to root '" + rootName + "': " + ex.Message);
					}
				}
			}
		}
	}
	public class SettingsBuilder
	{
		private readonly GameObject panel;

		private readonly string prefix;

		public int BindCount { get; private set; }

		public SettingsBuilder(GameObject panel, string prefix)
		{
			this.panel = panel;
			this.prefix = prefix;
		}

		public void Bind(string panelName, BoolSetting setting, string label = null, string path = null)
		{
			if (!string.IsNullOrEmpty(path))
			{
				Toggle val = Prefab.ComponentAtPath<Toggle>(panel, path);
				if ((Object)(object)val == (Object)null)
				{
					ModSettings.Trace("Bind(Bool) path not found: " + path);
					return;
				}
				BindToggleComponent(val, setting, label);
				BindCount++;
				return;
			}
			Toggle toggle = Prefab.Component<Toggle>(panel, panelName, "Toggle_" + prefix + panelName);
			if ((Object)(object)toggle == (Object)null)
			{
				return;
			}
			toggle.isOn = setting.Value;
			string text = "Toggle_" + prefix + panelName;
			int instanceID = ((Object)toggle).GetInstanceID();
			ApplyLabel(panelName, text, label);
			bool syncing = false;
			Prefab.BindToggle(toggle, UnityAction<bool>.op_Implicit((Action<bool>)delegate
			{
				if (!syncing)
				{
					setting.Set(toggle.isOn);
				}
			}));
			setting.Changed += delegate(bool isOn)
			{
				if (!syncing)
				{
					syncing = true;
					toggle.isOn = isOn;
					syncing = false;
				}
			};
			ModSettings.Trace("Bind(Bool) " + text + " subscribed, isOn=" + toggle.isOn + " id=" + instanceID);
			BindCount++;
		}

		private static void BindToggleComponent(Toggle toggle, BoolSetting setting, string label)
		{
			toggle.isOn = setting.Value;
			if (!string.IsNullOrEmpty(label))
			{
				Text componentInChildren = ((Component)toggle).GetComponentInChildren<Text>();
				if ((Object)(object)componentInChildren != (Object)null)
				{
					Prefab.ApplyLabel(componentInChildren, label);
				}
			}
			bool syncing = false;
			Prefab.BindToggle(toggle, UnityAction<bool>.op_Implicit((Action<bool>)delegate
			{
				if (!syncing)
				{
					setting.Set(toggle.isOn);
				}
			}));
			setting.Changed += delegate(bool val)
			{
				if (!syncing)
				{
					syncing = true;
					toggle.isOn = val;
					syncing = false;
				}
			};
		}

		public void Bind(string panelName, RangeSetting setting, string label = null, RangePaths? paths = null)
		{
			if (paths.HasValue)
			{
				RangePaths value = paths.Value;
				Slider val = Prefab.ComponentAtPath<Slider>(panel, value.MinSlider);
				Slider val2 = Prefab.ComponentAtPath<Slider>(panel, value.MaxSlider);
				if ((Object)(object)val == (Object)null || (Object)(object)val2 == (Object)null)
				{
					ModSettings.Trace("Range path sliders not found: min=" + value.MinSlider + " max=" + value.MaxSlider);
					return;
				}
				Toggle enableToggle = (string.IsNullOrEmpty(value.Toggle) ? null : Prefab.ComponentAtPath<Toggle>(panel, value.Toggle));
				Text componentInChildren = ((Component)val).GetComponentInChildren<Text>();
				BindRangeComponents(enableToggle, val, val2, componentInChildren, setting, label);
				BindCount++;
			}
			else
			{
				Toggle enableToggle2 = Prefab.Component<Toggle>(panel, panelName, "Toggle_" + prefix + panelName);
				Text valueText = Prefab.FindText(panel, panelName, "Toggle_" + prefix + panelName);
				Slider val3 = Prefab.Component<Slider>(panel, panelName, "Slider_" + prefix + panelName + "_Min");
				Slider val4 = Prefab.Component<Slider>(panel, panelName, "Slider_" + prefix + panelName + "_Max");
				if (!((Object)(object)val3 == (Object)null) || !((Object)(object)val4 == (Object)null))
				{
					BindRangeComponents(enableToggle2, val3, val4, valueText, setting, label);
					BindCount++;
				}
			}
		}

		private void BindRangeComponents(Toggle enableToggle, Slider sMin, Slider sMax, Text valueText, RangeSetting setting, string label)
		{
			if ((Object)(object)enableToggle != (Object)null)
			{
				enableToggle.isOn = setting.Enabled;
				if (!string.IsNullOrEmpty(label))
				{
					Text componentInChildren = ((Component)enableToggle).GetComponentInChildren<Text>();
					if ((Object)(object)componentInChildren != (Object)null)
					{
						Prefab.ApplyLabel(componentInChildren, label);
					}
				}
				Prefab.BindToggle(enableToggle, UnityAction<bool>.op_Implicit((Action<bool>)delegate
				{
					setting.SetEnabled(enableToggle.isOn);
				}));
			}
			else if (!setting.Enabled)
			{
				setting.SetEnabled(val: true);
			}
			ConfigureSlider(sMin, setting.MinLimit, setting.MaxLimit, setting.Min);
			ConfigureSlider(sMax, setting.MinLimit, setting.MaxLimit, setting.Max);
			bool syncing = false;
			if ((Object)(object)sMin != (Object)null)
			{
				SliderHook.Register(sMin, delegate(float v)
				{
					if (!syncing)
					{
						setting.SetMin(v);
						if ((Object)(object)sMax != (Object)null && sMax.value < setting.Min)
						{
							sMax.value = setting.Min;
						}
						UpdateText(valueText, setting.FormatRange());
					}
				});
			}
			if ((Object)(object)sMax != (Object)null)
			{
				SliderHook.Register(sMax, delegate(float v)
				{
					if (!syncing)
					{
						setting.SetMax(v);
						if ((Object)(object)sMin != (Object)null && sMin.value > setting.Max)
						{
							sMin.value = setting.Max;
						}
						UpdateText(valueText, setting.FormatRange());
					}
				});
			}
			UpdateText(valueText, setting.FormatRange());
			setting.Changed += delegate
			{
				if (!syncing)
				{
					syncing = true;
					if ((Object)(object)sMin != (Object)null)
					{
						sMin.value = setting.Min;
					}
					if ((Object)(object)sMax != (Object)null)
					{
						sMax.value = setting.Max;
					}
					if ((Object)(object)enableToggle != (Object)null)
					{
						enableToggle.isOn = setting.Enabled;
					}
					UpdateText(valueText, setting.FormatRange());
					syncing = false;
				}
			};
		}

		public void Bind(string panelName, FloatSetting setting, string label = null, FloatPaths? paths = null)
		{
			if (paths.HasValue)
			{
				FloatPaths value = paths.Value;
				Slider val = Prefab.ComponentAtPath<Slider>(panel, value.Slider);
				if ((Object)(object)val == (Object)null)
				{
					ModSettings.Trace("Float path slider not found: " + value.Slider);
					return;
				}
				Toggle enableToggle = (string.IsNullOrEmpty(value.Toggle) ? null : Prefab.ComponentAtPath<Toggle>(panel, value.Toggle));
				Text componentInChildren = ((Component)val).GetComponentInChildren<Text>();
				BindFloatComponents(enableToggle, val, componentInChildren, setting, label);
				BindCount++;
			}
			else
			{
				Toggle enableToggle2 = Prefab.Component<Toggle>(panel, panelName, "Toggle_" + prefix + panelName);
				Text valueText = Prefab.FindText(panel, panelName, "Toggle_" + prefix + panelName);
				Slider val2 = Prefab.Component<Slider>(panel, panelName, "Slider_" + prefix + panelName);
				if (!((Object)(object)val2 == (Object)null))
				{
					BindFloatComponents(enableToggle2, val2, valueText, setting, label);
					BindCount++;
				}
			}
		}

		private void BindFloatComponents(Toggle enableToggle, Slider slider, Text valueText, FloatSetting setting, string label)
		{
			if ((Object)(object)enableToggle != (Object)null)
			{
				enableToggle.isOn = setting.Enabled;
				if (!string.IsNullOrEmpty(label))
				{
					Text componentInChildren = ((Component)enableToggle).GetComponentInChildren<Text>();
					if ((Object)(object)componentInChildren != (Object)null)
					{
						Prefab.ApplyLabel(componentInChildren, label);
					}
				}
				Prefab.BindToggle(enableToggle, UnityAction<bool>.op_Implicit((Action<bool>)delegate
				{
					setting.SetEnabled(enableToggle.isOn);
				}));
			}
			else if (!setting.Enabled)
			{
				setting.SetEnabled(val: true);
			}
			if (setting.HasLimits)
			{
				ConfigureSlider(slider, setting.MinLimit, setting.MaxLimit, setting.Value);
			}
			else
			{
				slider.value = setting.Value;
			}
			float maxLimit = slider.maxValue;
			bool syncing = false;
			SliderHook.Register(slider, delegate(float v)
			{
				if (!syncing)
				{
					setting.SetValue(v);
					UpdateText(valueText, setting.FormatValue(maxLimit));
				}
			});
			UpdateText(valueText, setting.FormatValue(maxLimit));
			setting.Changed += delegate
			{
				if (!syncing)
				{
					syncing = true;
					slider.value = setting.Value;
					if ((Object)(object)enableToggle != (Object)null)
					{
						enableToggle.isOn = setting.Enabled;
					}
					UpdateText(valueText, setting.FormatValue(maxLimit));
					syncing = false;
				}
			};
		}

		public void BindRadio(string groupPanel, RadioSetting setting, RadioPaths? paths = null)
		{
			if (paths.HasValue)
			{
				RadioPaths value = paths.Value;
				if (value.Toggles == null || value.Toggles.Length != setting.OptionNames.Length)
				{
					Instance logger_instance = Main.logger_instance;
					if (logger_instance != null)
					{
						string[] obj = new string[5] { "BindRadio path mode: paths.Toggles length (", null, null, null, null };
						string[] toggles = value.Toggles;
						obj[1] = ((toggles != null) ? toggles.Length : 0).ToString();
						obj[2] = ") != optionNames length (";
						obj[3] = setting.OptionNames.Length.ToString();
						obj[4] = ")";
						logger_instance.Error(string.Concat(obj));
					}
					return;
				}
				Toggle[] array = (Toggle[])(object)new Toggle[value.Toggles.Length];
				for (int i = 0; i < value.Toggles.Length; i++)
				{
					array[i] = Prefab.ComponentAtPath<Toggle>(panel, value.Toggles[i]);
					if ((Object)(object)array[i] == (Object)null)
					{
						ModSettings.Trace("Radio path not found: " + value.Toggles[i]);
						return;
					}
				}
				BindRadioComponents(array, setting);
				BindCount++;
				return;
			}
			GameObject val = Prefab.Child(panel, groupPanel);
			if (!((Object)(object)val == (Object)null))
			{
				Toggle[] array2 = (Toggle[])(object)new Toggle[setting.OptionNames.Length];
				for (int j = 0; j < setting.OptionNames.Length; j++)
				{
					string text = setting.OptionNames[j];
					array2[j] = Prefab.Component<Toggle>(val, text, "Toggle_" + prefix + text);
				}
				BindRadioComponents(array2, setting);
				ModSettings.Trace("BindRadio " + groupPanel + " subscribed " + setting.OptionNames.Length + " options");
				BindCount++;
			}
		}

		private void BindRadioComponents(Toggle[] toggles, RadioSetting setting)
		{
			bool syncing = false;
			Action syncToggles = delegate
			{
				if (!syncing)
				{
					syncing = true;
					for (int i = 0; i < toggles.Length; i++)
					{
						if ((Object)(object)toggles[i] != (Object)null)
						{
							toggles[i].isOn = setting.IsSelected(i);
						}
					}
					syncing = false;
				}
			};
			for (int num = 0; num < toggles.Length; num++)
			{
				int idx = num;
				Toggle toggle = toggles[idx];
				if ((Object)(object)toggle == (Object)null)
				{
					continue;
				}
				toggle.isOn = setting.IsSelected(idx);
				Prefab.BindToggle(toggle, UnityAction<bool>.op_Implicit((Action<bool>)delegate
				{
					if (!syncing)
					{
						setting.Select(idx, toggle.isOn);
						syncToggles();
					}
				}));
			}
			setting.Changed += syncToggles;
		}

		public void BindDropdown(string panelName, DropdownSetting setting, string label = null, string path = null)
		{
			if (!string.IsNullOrEmpty(path))
			{
				Dropdown val = Prefab.ComponentAtPath<Dropdown>(panel, path);
				if ((Object)(object)val == (Object)null)
				{
					ModSettings.Trace("BindDropdown path not found: " + path);
					return;
				}
				BindDropdownComponent(val, setting, label);
				BindCount++;
				return;
			}
			Dropdown dropdown = Prefab.Component<Dropdown>(panel, panelName, "Dropdown_" + prefix + panelName);
			if ((Object)(object)dropdown == (Object)null)
			{
				return;
			}
			if (setting.Options.Length != 0)
			{
				ApplyDropdownOptions(dropdown, setting.Options);
			}
			dropdown.value = setting.Value;
			string text = "Dropdown_" + prefix + panelName;
			ApplyLabel(panelName, text, label);
			bool syncing = false;
			Prefab.BindDropdown(dropdown, UnityAction<int>.op_Implicit((Action<int>)delegate(int v)
			{
				if (!syncing)
				{
					setting.Set(v);
				}
			}));
			setting.applyOptions = delegate(string[] opts)
			{
				ApplyDropdownOptions(dropdown, opts);
			};
			setting.Changed += delegate(int value)
			{
				if (!syncing)
				{
					syncing = true;
					dropdown.value = value;
					syncing = false;
				}
			};
			ModSettings.Trace("BindDropdown " + text + " subscribed, value=" + dropdown.value + " options=" + setting.Options.Length);
			BindCount++;
		}

