			Prefab.BindDropdown(dropdown, UnityAction<int>.op_Implicit((Action<int>)delegate(int v)
			{
				if (!syncing)
				{
					setting.Set(v);
				}
			}));
			setting.applyOptions = delegate(string[] opts)
