		private void BindKeybindComponents(Button captureBtn, Button resetBtn, Text rowLabelText, KeybindSetting setting, string label, string resetLabel)
		{
			if ((Object)(object)rowLabelText != (Object)null && !string.IsNullOrEmpty(label))
			{
				Prefab.ApplyLabel(rowLabelText, label);
			}
			if ((Object)(object)resetBtn != (Object)null)
			{
				Text componentInChildren = ((Component)resetBtn).GetComponentInChildren<Text>();
				if ((Object)(object)componentInChildren != (Object)null)
				{
					Prefab.ApplyLabel(componentInChildren, resetLabel ?? "Reset");
				}
			}
			Text displayText = ((Component)captureBtn).GetComponentInChildren<Text>();
			if ((Object)(object)displayText != (Object)null)
			{
				displayText.text = KeybindFormat.FriendlyWithDefault(setting.Value, setting.DefaultValue);
			}
			setting.Changed += delegate(string newVal)
			{
				if ((Object)(object)displayText != (Object)null)
				{
					displayText.text = KeybindFormat.FriendlyWithDefault(newVal, setting.DefaultValue);
				}
			};
			int captureId = ((Object)captureBtn).GetInstanceID();
			Prefab.BindButton(captureBtn, UnityAction.op_Implicit((Action)delegate
			{
				ModSettings.Trace("Keybind capture started: id=" + captureId);
				if ((Object)(object)displayText != (Object)null)
				{
					displayText.text = "Press any key…";
				}
				KeybindCapture.Begin(setting, displayText);
			}));
			if ((Object)(object)resetBtn != (Object)null)
			{
				Prefab.BindButton(resetBtn, UnityAction.op_Implicit((Action)delegate
				{
					ModSettings.Trace("Keybind reset id=" + captureId + " -> " + setting.DefaultValue);
					KeybindCapture.Cancel();
					setting.ResetToDefault();
				}));
			}
			ModSettings.Trace("BindKeybind id=" + captureId + " subscribed, value=" + setting.Value);
		}

