	public class SettingsGroup
	{
		private enum EntryType
		{
			Bool,
			Float,
			Range,
			Dropdown,
			Radio,
			Button,
			Header,
			Keybind
		}

		private readonly struct Entry(string key, string panel, EntryType type, string label = null, BoolSetting boolSetting = null, FloatSetting floatSetting = null, RangeSetting rangeSetting = null, DropdownSetting dropdownSetting = null, RadioSetting radioSetting = null, ActionBinding actionBinding = null, HeaderSetting headerSetting = null, KeybindSetting keybindSetting = null, string resetLabel = null, string widgetPath = null, FloatPaths? floatPaths = null, RangePaths? rangePaths = null, KeybindPaths? keybindPaths = null, RadioPaths? radioPaths = null)
		{
			public readonly string Key = key;

			public readonly string Panel = panel;

			public readonly string Label = label;

			public readonly string ResetLabel = resetLabel;

			public readonly string WidgetPath = widgetPath;

			public readonly EntryType Type = type;

			public readonly BoolSetting BoolSetting = boolSetting;

			public readonly FloatSetting FloatSetting = floatSetting;

			public readonly RangeSetting RangeSetting = rangeSetting;

			public readonly DropdownSetting DropdownSetting = dropdownSetting;

			public readonly RadioSetting RadioSetting = radioSetting;

			public readonly ActionBinding ActionBinding = actionBinding;

			public readonly HeaderSetting HeaderSetting = headerSetting;

			public readonly KeybindSetting KeybindSetting = keybindSetting;

			public readonly FloatPaths? FloatPaths = floatPaths;

			public readonly RangePaths? RangePaths = rangePaths;

			public readonly KeybindPaths? KeybindPaths = keybindPaths;

			public readonly RadioPaths? RadioPaths = radioPaths;
		}

		private readonly List<Entry> entries = new List<Entry>();

		private Action<GameObject, GameObject> customBind;

		public string Name { get; }

		public string RootName { get; private set; } = "Hud";

		public string TabId { get; private set; }

		public string ContentObjectName { get; private set; }

		public string MenuButtonName { get; private set; }

		public string UiPrefix { get; private set; } = "";

		public string ViewportPanel { get; private set; }

		public string ViewportContent { get; private set; }

		public bool HasTab => TabId != null;

		public SettingsGroup(string name)
		{
			Name = name;
			ModSettings.RegisterGroup(this);
		}

		public SettingsGroup Root(string rootName)
		{
			RootName = rootName ?? "Hud";
			return this;
		}

		public SettingsGroup Tab(string tabId, string menuButton)
		{
			TabId = tabId;
			MenuButtonName = menuButton;
			return this;
		}

		public SettingsGroup Content(string contentObjectName)
		{
			ContentObjectName = contentObjectName;
			return this;
		}

		public SettingsGroup Viewport(string panel, string content)
		{
			ViewportPanel = panel;
			ViewportContent = content;
			return this;
		}

		public SettingsGroup Prefix(string uiPrefix)
		{
			UiPrefix = uiPrefix;
			return this;
		}

		public SettingsGroup OnBind(Action<GameObject, GameObject> callback)
		{
			customBind = callback;
			return this;
		}

		public BoolSetting Bool(string key, bool defaultValue = false, string panel = null, string label = null, string path = null)
		{
			BoolSetting boolSetting = new BoolSetting(defaultValue);
			entries.Add(new Entry(key, panel ?? key, EntryType.Bool, label, boolSetting, null, null, null, null, null, null, null, null, path));
			return boolSetting;
		}

		public FloatSetting Float(string key, float defaultValue = 0f, bool defaultEnabled = false, DisplayFormat format = DisplayFormat.Raw, float min = 0f, float max = 0f, string panel = null, string label = null, FloatPaths? paths = null)
		{
			FloatSetting floatSetting = new FloatSetting(defaultValue, defaultEnabled, format, min, max);
			entries.Add(new Entry(key, panel ?? key, EntryType.Float, label, null, floatSetting, null, null, null, null, null, null, null, null, paths));
			return floatSetting;
		}

		public RangeSetting Range(string key, float minLimit = 0f, float maxLimit = 255f, float? defaultMin = null, float? defaultMax = null, bool defaultEnabled = false, DisplayFormat format = DisplayFormat.Raw, string panel = null, string label = null, RangePaths? paths = null)
		{
			RangeSetting rangeSetting = new RangeSetting(minLimit, maxLimit, defaultMin, defaultMax, defaultEnabled, format);
			entries.Add(new Entry(key, panel ?? key, EntryType.Range, label, null, null, rangeSetting, null, null, null, null, null, null, null, null, paths));
			return rangeSetting;
		}

		public DropdownSetting Dropdown(string key, int defaultValue = 0, string[] options = null, string panel = null, string label = null, string path = null)
		{
			DropdownSetting dropdownSetting = new DropdownSetting(defaultValue, options);
			entries.Add(new Entry(key, panel ?? key, EntryType.Dropdown, label, null, null, null, dropdownSetting, null, null, null, null, null, path));
			return dropdownSetting;
		}

		public RadioSetting Radio(string key, string radioPanel, params string[] optionNames)
		{
			RadioSetting radioSetting = new RadioSetting(optionNames);
			entries.Add(new Entry(key, radioPanel, EntryType.Radio, null, null, null, null, null, radioSetting));
			return radioSetting;
		}

		public RadioSetting RadioWithPaths(string key, RadioPaths paths, params string[] optionNames)
		{
			RadioSetting radioSetting = new RadioSetting(optionNames);
			List<Entry> list = entries;
			RadioPaths? radioPaths = paths;
			list.Add(new Entry(key, key, EntryType.Radio, null, null, null, null, null, radioSetting, null, null, null, null, null, null, null, null, radioPaths));
			return radioSetting;
		}

		public ActionBinding Button(string key, string label = null, string path = null)
		{
			ActionBinding actionBinding = new ActionBinding();
			entries.Add(new Entry(key, key, EntryType.Button, label, null, null, null, null, null, actionBinding, null, null, null, path));
			return actionBinding;
		}

		public HeaderSetting Header(string key, string label, string panel = null, string path = null)
		{
			HeaderSetting headerSetting = new HeaderSetting(label);
			entries.Add(new Entry(key, panel ?? key, EntryType.Header, label, null, null, null, null, null, null, headerSetting, null, null, path));
			return headerSetting;
		}

		public KeybindSetting Keybind(string key, string defaultBinding = "", string panel = null, string label = null, string resetLabel = null, KeybindPaths? paths = null)
		{
			KeybindSetting keybindSetting = new KeybindSetting(defaultBinding);
			entries.Add(new Entry(key, panel ?? key, EntryType.Keybind, label, null, null, null, null, null, null, null, keybindSetting, resetLabel, null, null, null, paths));
			return keybindSetting;
		}

		public void ResolveAndBind(GameObject contentObj)
		{
			GameObject val = ((ViewportPanel != null) ? Prefab.ViewportContent(contentObj, ViewportPanel, ViewportContent) : contentObj);
			if (!((Object)(object)val == (Object)null))
			{
				BindAll(contentObj, val, new SettingsBuilder(val, UiPrefix));
			}
		}

		private void BindAll(GameObject contentObj, GameObject viewportContent, SettingsBuilder builder)
		{
			int num = 0;
			int num2 = 0;
			foreach (Entry entry in entries)
			{
				try
				{
					int bindCount = builder.BindCount;
					switch (entry.Type)
					{
					case EntryType.Bool:
						builder.Bind(entry.Panel, entry.BoolSetting, entry.Label, entry.WidgetPath);
						break;
					case EntryType.Float:
						builder.Bind(entry.Panel, entry.FloatSetting, entry.Label, entry.FloatPaths);
						break;
					case EntryType.Range:
						builder.Bind(entry.Panel, entry.RangeSetting, entry.Label, entry.RangePaths);
						break;
					case EntryType.Dropdown:
						builder.BindDropdown(entry.Panel, entry.DropdownSetting, entry.Label, entry.WidgetPath);
						break;
					case EntryType.Radio:
						builder.BindRadio(entry.Panel, entry.RadioSetting, entry.RadioPaths);
						break;
					case EntryType.Button:
						builder.BindButton(entry.Key, entry.ActionBinding, entry.Label, entry.WidgetPath);
						break;
					case EntryType.Header:
						builder.BindHeader(entry.Panel, entry.HeaderSetting, entry.Label, entry.WidgetPath);
						break;
					case EntryType.Keybind:
						builder.BindKeybind(entry.Panel, entry.KeybindSetting, entry.Label, entry.ResetLabel, entry.KeybindPaths);
						break;
					}
					if (builder.BindCount > bindCount)
					{
						num++;
						continue;
					}
				}
				catch (Exception ex)
				{
					Instance logger_instance = Main.logger_instance;
					if (logger_instance != null)
					{
						logger_instance.Warning("SettingsGroup " + Name + ": Exception binding '" + entry.Key + "': " + ex.Message);
					}
				}
				num2++;
				Instance logger_instance2 = Main.logger_instance;
				if (logger_instance2 != null)
				{
					logger_instance2.Warning("SettingsGroup " + Name + ": Failed to bind '" + entry.Key + "' (panel: '" + entry.Panel + "')");
				}
			}
			try
			{
				customBind?.Invoke(contentObj, viewportContent);
			}
			catch (Exception ex2)
			{
				Instance logger_instance3 = Main.logger_instance;
				if (logger_instance3 != null)
				{
					logger_instance3.Warning("SettingsGroup " + Name + ": Custom bind failed: " + ex2.Message);
				}
			}
			Instance logger_instance4 = Main.logger_instance;
			if (logger_instance4 != null)
			{
				logger_instance4.Msg("SettingsGroup " + Name + ": Bound " + num + "/" + (num + num2) + " settings");
			}
		}

		public void Save(JObject root)
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_0007: Expected O, but got Unknown
			JObject val = new JObject();
			foreach (Entry entry in entries)
			{
				SaveEntry(val, entry);
			}
			root[Name] = (JToken)(object)val;
		}

		public void Load(JObject root)
		{
			JToken obj = root[Name];
			JObject val = (JObject)(object)((obj is JObject) ? obj : null);
			if (val == null)
			{
				return;
			}
			foreach (Entry entry in entries)
			{
				LoadEntry(val, entry);
			}
		}

		private static void SaveEntry(JObject section, Entry e)
		{
