	public enum DisplayFormat
	{
		Raw,
		Tier,
		Percent,
		Seconds,
		Multiplier
	}
	public static class DisplayFormatHelper
	{
		public static string Format(float val, DisplayFormat fmt, float maxLimit = 0f)
		{
			return fmt switch
			{
				DisplayFormat.Tier => ((int)val + 1).ToString(), 
				DisplayFormat.Percent => FormatPercent(val, maxLimit), 
				DisplayFormat.Seconds => (int)val + " sec", 
				DisplayFormat.Multiplier => val.ToString("F1"), 
				_ => ((int)val).ToString(), 
			};
		}

		private static string FormatPercent(float val, float maxLimit)
		{
			if (maxLimit > 0f && maxLimit != 100f)
			{
				return (int)(val / maxLimit * 100f) + " %";
			}
			return (int)val + " %";
		}
	}
