		public RangeSetting(float minLimit = 0f, float maxLimit = 255f, float? defaultMin = null, float? defaultMax = null, bool defaultEnabled = false, DisplayFormat format = DisplayFormat.Raw)
		{
			MinLimit = minLimit;
			MaxLimit = maxLimit;
