			Max = defaultMax ?? maxLimit;
			Enabled = defaultEnabled;
			Format = format;
		}

		public void SetEnabled(bool val)
		{
			ModSettings.Trace("RangeSetting.SetEnabled: before=" + Enabled + " requested=" + val);
