	public static class TabManager
	{
		private class Tab
		{
			private readonly SettingsGroup group;

			private GameObject contentObj;

			public string Id => group.TabId;

			public string MenuButtonName => group.MenuButtonName;

			public Tab(SettingsGroup group)
			{
				this.group = group;
			}

			public void Init(GameObject contentRoot)
			{
				contentObj = Prefab.Child(contentRoot, group.ContentObjectName);
				if (!((Object)(object)contentObj == (Object)null))
				{
					group.ResolveAndBind(contentObj);
				}
			}

			public void SetActive(bool active)
			{
				if ((Object)(object)contentObj != (Object)null)
				{
					contentObj.SetActive(active);
				}
			}
		}

		private static readonly List<Tab> tabs = new List<Tab>();

		private static readonly Dictionary<string, Tab> tabById = new Dictionary<string, Tab>();

		private static Tab activeTab;

		public static string ActiveTabId => activeTab?.Id;

		public static void Init(GameObject contentRoot, GameObject menuContent)
		{
			Clear();
			foreach (SettingsGroup allGroup in ModSettings.AllGroups)
			{
				if (allGroup.HasTab)
				{
					Tab tab = new Tab(allGroup);
					tabs.Add(tab);
					tabById[tab.Id] = tab;
				}
			}
			foreach (Tab tab2 in tabs)
			{
				try
				{
					tab2.Init(contentRoot);
				}
				catch (Exception ex)
				{
					Instance logger_instance = Main.logger_instance;
					if (logger_instance != null)
					{
						logger_instance.Error("TabManager: Failed to init tab '" + tab2.Id + "': " + ex.Message);
					}
				}
				tab2.SetActive(active: false);
			}
			WireMenuButtons(menuContent);
			Instance logger_instance2 = Main.logger_instance;
			if (logger_instance2 != null)
			{
				logger_instance2.Msg("TabManager: Created " + tabs.Count + " tab(s)");
			}
		}

		public static void ActivateTab(string tabId)
		{
			if (tabById.TryGetValue(tabId, out var value))
			{
				if (activeTab == value)
				{
					value.SetActive(active: false);
					activeTab = null;
				}
				else
				{
					DeactivateAll();
					value.SetActive(active: true);
					activeTab = value;
				}
			}
		}

		public static void DeactivateAll()
		{
			foreach (Tab tab in tabs)
			{
				tab.SetActive(active: false);
			}
			activeTab = null;
		}

		public static void Clear()
		{
			tabs.Clear();
			tabById.Clear();
			activeTab = null;
			SliderHook.Clear();
		}

		private static void WireMenuButtons(GameObject menuContent)
		{
			int num = 0;
			foreach (Tab tab in tabs)
			{
				GameObject val = Prefab.Child(menuContent, tab.MenuButtonName);
				if ((Object)(object)val == (Object)null)
				{
					Instance logger_instance = Main.logger_instance;
					if (logger_instance != null)
					{
						logger_instance.Warning("TabManager: Menu button '" + tab.MenuButtonName + "' not found for tab '" + tab.Id + "'");
					}
					continue;
				}
				Button component = val.GetComponent<Button>();
				if (!((Object)(object)component == (Object)null))
				{
					Prefab.BindButton(component, UnityAction.op_Implicit((Action)delegate
					{
						ActivateTab(tab.Id);
					}));
					num++;
				}
			}
			Instance logger_instance2 = Main.logger_instance;
			if (logger_instance2 != null)
			{
				logger_instance2.Msg("TabManager: Wired " + num + "/" + tabs.Count + " menu button(s)");
			}
		}
	}
	internal static class KeybindCapture
	{
		private static KeybindSetting current;

		private static Text displayText;

		private static bool[] gamepadSnapshot;

		public static bool Active => current != null;

		public static void Begin(KeybindSetting setting, Text display)
		{
			current = setting;
			displayText = display;
			gamepadSnapshot = null;
		}

		public static void Cancel()
		{
			if (current != null && (Object)(object)displayText != (Object)null)
			{
				displayText.text = KeybindFormat.Friendly(current.Value);
			}
			current = null;
			displayText = null;
			gamepadSnapshot = null;
		}

		public static void Tick()
		{
			if (current != null)
			{
				if (Input.GetKeyDown((KeyCode)27))
				{
					Cancel();
				}
				else if (!Input.anyKeyDown || !TryCaptureKeyboard())
				{
					TryCaptureGamepad();
				}
			}
		}

		private static bool TryCaptureKeyboard()
		{
			//IL_001f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0024: Unknown result type (might be due to invalid IL or missing references)
			//IL_0026: Unknown result type (might be due to invalid IL or missing references)
			//IL_0028: Invalid comparison between Unknown and I4
			//IL_0030: Unknown result type (might be due to invalid IL or missing references)
			//IL_0033: Invalid comparison between Unknown and I4
			//IL_003b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0041: Invalid comparison between Unknown and I4
			//IL_0043: Unknown result type (might be due to invalid IL or missing references)
			//IL_0049: Invalid comparison between Unknown and I4
			//IL_0056: Unknown result type (might be due to invalid IL or missing references)
			foreach (KeyCode value in Enum.GetValues(typeof(KeyCode)))
			{
				if ((int)value == 0 || (int)value == 27 || (int)value == 323 || (int)value == 324 || !Input.GetKeyDown(value))
				{
					continue;
				}
				Commit("kb:" + ((object)value/*cast due to .constrained prefix*/).ToString());
				return true;
			}
			return false;
		}

		private static void TryCaptureGamepad()
		{
			IGamepadTemplate val = KeybindRewired.ActiveTemplate();
			if (val == null)
			{
				return;
			}
			int buttonCount = KeybindRewired.ButtonCount;
			if (gamepadSnapshot == null)
			{
				gamepadSnapshot = new bool[buttonCount];
				for (int i = 0; i < buttonCount; i++)
				{
					gamepadSnapshot[i] = KeybindRewired.ButtonHeldAt(val, i);
				}
				return;
			}
			for (int j = 0; j < buttonCount; j++)
			{
				bool flag = KeybindRewired.ButtonHeldAt(val, j);
				bool flag2 = gamepadSnapshot[j];
				gamepadSnapshot[j] = flag;
				if (flag && !flag2)
				{
					Commit("gp:" + KeybindRewired.ButtonNameAt(j));
					break;
				}
			}
		}

		private static void Commit(string binding)
		{
			ModSettings.Trace("KeybindCapture committed: " + binding);
			KeybindSetting keybindSetting = current;
			current = null;
			displayText = null;
			gamepadSnapshot = null;
			keybindSetting.Set(binding);
		}
	}
	internal static class KeybindFormat
	{
		public static string Friendly(string binding)
		{
			if (string.IsNullOrEmpty(binding))
			{
				return "(none)";
			}
			if (binding.StartsWith("kb:"))
			{
				return binding.Substring(3);
			}
			if (binding.StartsWith("gp:"))
			{
				return "[GP] " + binding.Substring(3);
			}
			return binding;
		}

		public static string FriendlyWithDefault(string binding, string defaultBinding)
		{
			if (!string.IsNullOrEmpty(binding))
			{
				return Friendly(binding);
			}
			if (string.IsNullOrEmpty(defaultBinding))
			{
				return "(none)";
			}
			return "(none) (default: " + Friendly(defaultBinding) + ")";
		}
	}
	public static class KeybindMatcher
	{
		public static bool IsHeld(string binding)
		{
			//IL_002e: Unknown result type (might be due to invalid IL or missing references)
			if (string.IsNullOrEmpty(binding))
			{
				return false;
			}
			KeyCode result;
			if (binding.StartsWith("kb:"))
			{
				return Enum.TryParse<KeyCode>(binding.Substring(3), out result) && Input.GetKey(result);
			}
			if (binding.StartsWith("gp:"))
			{
				return KeybindRewired.ButtonHeldByName(binding.Substring(3));
			}
			return false;
		}
	}
	internal static class KeybindRewired
	{
		private static readonly (string Name, Func<IGamepadTemplate, IControllerTemplateButton> Get)[] Buttons = new(string, Func<IGamepadTemplate, IControllerTemplateButton>)[15]
		{
			("A", (IGamepadTemplate t) => t.a),
			("B", (IGamepadTemplate t) => t.b),
			("X", (IGamepadTemplate t) => t.x),
			("Y", (IGamepadTemplate t) => t.y),
			("LB", (IGamepadTemplate t) => t.leftBumper),
			("RB", (IGamepadTemplate t) => t.rightBumper),
			("Back", (IGamepadTemplate t) => t.back),
			("Start", (IGamepadTemplate t) => t.start),
			("Guide", (IGamepadTemplate t) => t.guide),
