		public static int ButtonCount => Buttons.Length;

		public static string ButtonNameAt(int index)
		{
			return Buttons[index].Name;
		}

		public static IGamepadTemplate ActiveTemplate()
		{
			try
			{
				EpochInputManager epoch_input_manager = Refs_Manager.epoch_input_manager;
				Player val = ((epoch_input_manager != null) ? epoch_input_manager.rewiredPlayer : null);
				if (val == null || val.IsNullOrDestroyed())
				{
					return null;
				}
				Controller lastActiveController = val.controllers.GetLastActiveController((ControllerType)2);
				if (lastActiveController == null)
				{
					return null;
				}
				GamepadTemplate template = lastActiveController.GetTemplate<GamepadTemplate>();
				if (template == null)
				{
					return null;
				}
				return ((Il2CppObjectBase)template).Cast<IGamepadTemplate>();
			}
			catch
			{
				return null;
			}
		}

		public static bool ButtonHeldAt(IGamepadTemplate template, int index)
		{
			if (template == null)
			{
				return false;
			}
			try
			{
				IControllerTemplateButton val = Buttons[index].Get(template);
				return val != null && val.value;
			}
			catch
			{
				return false;
			}
		}

		public static bool ButtonHeldByName(string elementName)
		{
			IGamepadTemplate val = ActiveTemplate();
			if (val == null)
			{
				return false;
			}
			for (int i = 0; i < Buttons.Length; i++)
			{
				if (Buttons[i].Name == elementName)
				{
					return ButtonHeldAt(val, i);
				}
			}
			return false;
		}
	}
