			public static void AddSkill(string ability_name, float damage, bool hit, bool crit, bool kill, float overkill, string target_name)
			{
				//IL_001b: Unknown result type (might be due to invalid IL or missing references)
				//IL_0020: Unknown result type (might be due to invalid IL or missing references)
				if (!Skill_prefab.IsNullOrDestroyed())
				{
					GameObject val = Object.Instantiate<GameObject>(Skill_prefab, Vector3.zero, Quaternion.identity);
					val.active = false;
					val.transform.SetParent(DamageMeter_content.transform);
					Sprite icon = GetIcon(ability_name);
					List<float> list = new List<float>();
					list.Add(damage);
					List<bool> list2 = new List<bool>();
					list2.Add(hit);
					List<bool> list3 = new List<bool>();
					list3.Add(crit);
					List<bool> list4 = new List<bool>();
					list4.Add(kill);
					List<float> list5 = new List<float>();
					list5.Add(overkill);
					List<string> list6 = new List<string>();
					list6.Add(target_name);
					Skills.Add(new Skill
					{
						Obj = val,
						Icon = icon,
						AbilityName = ability_name,
						Damages = list,
						Hits = list2,
						Crits = list3,
						Kills = list4,
						Overkills = list5,
						TargetName = list6
					});
				}
			}

			public static void Update()
			{
				Current_Frame++;
				if (Current_Frame < Frames)
				{
					return;
				}
				Current_Frame = 0;
				foreach (Skill skill in Skills)
				{
					if (skill.Obj.IsNullOrDestroyed())
					{
						continue;
					}
					Button component = skill.Obj.GetComponent<Button>();
					if (!component.IsNullOrDestroyed())
					{
						Events.Set(component, UnityAction.op_Implicit(Events.OpenDetails_OnClick_Action));
					}
					GameObject child = Functions.GetChild(skill.Obj, "Infos");
					if (!child.IsNullOrDestroyed())
					{
						GameObject child2 = Functions.GetChild(child, "Icon");
						if (!child2.IsNullOrDestroyed())
						{
							GameObject child3 = Functions.GetChild(child2, "Image");
							if (!child3.IsNullOrDestroyed())
							{
								Image component2 = child3.GetComponent<Image>();
								if (!component2.IsNullOrDestroyed())
								{
									component2.sprite = skill.Icon;
								}
							}
						}
						GameObject child4 = Functions.GetChild(child, "SkillName");
						if (!child4.IsNullOrDestroyed())
						{
							GameObject child5 = Functions.GetChild(child4, "Text");
							if (!child5.IsNullOrDestroyed())
							{
								Text component3 = child5.GetComponent<Text>();
								if (!component3.IsNullOrDestroyed())
								{
									component3.text = skill.AbilityName;
								}
							}
						}
					}
					float num = 0f;
					foreach (float damage in skill.Damages)
					{
						num += damage;
					}
					if (!child.IsNullOrDestroyed())
					{
						GameObject child6 = Functions.GetChild(child, "Percent");
						if (!child6.IsNullOrDestroyed())
						{
							GameObject child7 = Functions.GetChild(child6, "Text");
							if (!child7.IsNullOrDestroyed())
							{
								Text component4 = child7.GetComponent<Text>();
								if (!component4.IsNullOrDestroyed())
								{
									bool flag = true;
									if (!DamageType_Dropdown.IsNullOrDestroyed() && DamageType_Dropdown.value == 1)
									{
										flag = false;
									}
									if (flag)
									{
										component4.text = (num * 100f / TotalDamageDeal).ToString("0.0") + " %";
									}
									else
									{
										component4.text = Convert.ToInt32(num).ToString();
									}
								}
							}
						}
					}
					GameObject child8 = Functions.GetChild(skill.Obj, "SkillBar");
					if (!child8.IsNullOrDestroyed())
					{
						Slider component5 = child8.GetComponent<Slider>();
						if (!component5.IsNullOrDestroyed())
						{
							component5.value = num * 100f / TotalDamageDeal;
						}
					}
					if (!skill.Obj.active)
					{
						skill.Obj.active = true;
					}
				}
			}

			public static Sprite GetIcon(string ability_name)
			{
				Sprite val = null;
				try
				{
					foreach (Ability ability in Abilities)
					{
						if (ability.abilityName == ability_name && !ability.abilitySprite.IsNullOrDestroyed())
						{
							val = ability.abilitySprite;
							break;
						}
					}
					if ((Object)(object)val == (Object)null)
					{
						Enumerator<Summoned> enumerator2 = Refs_Manager.summon_tracker.summons.GetEnumerator();
						while (enumerator2.MoveNext())
						{
							Summoned current2 = enumerator2.Current;
							AbilityList component = ((Component)current2).gameObject.GetComponent<AbilityList>();
							if (component.IsNullOrDestroyed())
							{
								continue;
							}
							Enumerator<Ability> enumerator3 = component.abilities.GetEnumerator();
							while (enumerator3.MoveNext())
							{
								Ability current3 = enumerator3.Current;
								if (current3.abilityName == ability_name)
								{
									CreationReferences component2 = ((Component)current2).gameObject.GetComponent<CreationReferences>();
									if (!component2.IsNullOrDestroyed() && !component2.thisAbility.IsNullOrDestroyed())
									{
										val = component2.thisAbility.abilitySprite;
									}
									break;
								}
							}
						}
					}
				}
				catch
				{
				}
				return val;
			}

			public static void Reset()
			{
				Skills = new List<Skill>();
				TotalDamageDeal = 0f;
				if (DamageMeter_content.IsNullOrDestroyed())
				{
