			Color.green,
			Color.white,
			Color.grey,
			Color.magenta,
			Color.black,
			Color.yellow
		};

		public static int Frames = 30;

		public static int Current_Frame = 0;

		public static DamageMeter instance { get; private set; }

		public DamageMeter(IntPtr ptr)
			: base(ptr)
		{
		}

		private void Awake()
		{
			instance = this;
			UI.Reset();
		}

		private void Update()
		{
			if (!Assets.Loaded())
			{
				Assets.Load();
			}
			else if (Scenes.IsGameScene())
			{
				if (Abilities.Count == 0 && On)
				{
					foreach (Ability item2 in Resources.FindObjectsOfTypeAll<Ability>())
					{
						if (!Abilities.Contains(item2))
						{
							Abilities.Add(item2);
						}
					}
					Ability[] abilities = Items_Mjolner.Trigger.Abilities;
					foreach (Ability item in abilities)
					{
						if (!Abilities.Contains(item))
						{
							Abilities.Add(item);
						}
					}
				}
				if (!UI.Initialized)
				{
					UI.Init();
					return;
				}
				if (!MenuText.IsNullOrDestroyed())
				{
					((TMP_Text)MenuText).text = "Damage Meter";
				}
				if (!DamageMeter_obj.IsNullOrDestroyed())
				{
					if (Input.GetKeyDown((KeyCode)117))
					{
						DamageMeter_obj.active = !DamageMeter_obj.active;
					}
					if (!DamageMeter_obj.active)
					{
						On = false;
					}
					if (On)
					{
						UI.Update();
					}
				}
				if (!OnOff_Image.IsNullOrDestroyed())
				{
					if (On)
					{
						OnOff_Image.sprite = On_sprite;
					}
					else
					{
						OnOff_Image.sprite = Off_sprite;
					}
				}
				if (!Reset_obj.IsNullOrDestroyed())
				{
					if (Skills.Count > 0)
					{
						Reset_obj.active = true;
					}
					else
					{
						Reset_obj.active = false;
					}
				}
			}
			else
			{
				On = false;
				Abilities = new List<Ability>();
				if (!DamageMeter_obj.IsNullOrDestroyed() && DamageMeter_obj.active)
				{
					DamageMeter_obj.active = false;
				}
				UI.Initialized = false;
			}
		}
	}
