		{
			//IL_002c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0031: Unknown result type (might be due to invalid IL or missing references)
			//IL_004e: Unknown result type (might be due to invalid IL or missing references)
			if (!starting_tp || Refs_Manager.player_spawn_manager.IsNullOrDestroyed() || Refs_Manager.player_actor.IsNullOrDestroyed())
			{
				return;
			}
			Scene activeScene = SceneManager.GetActiveScene();
			if (((Scene)(ref activeScene)).name != new_scene)
			{
				try
				{
					SceneManager.SetActiveScene(SceneManager.GetSceneByName(new_scene));
					return;
				}
				catch
				{
					return;
				}
			}
			starting_tp = false;
			PlayerSpawn val = null;
			Refs_Manager.player_spawn_manager.TryPlacePlayerAtSpawn(Refs_Manager.player_actor, old_scene, new_scene, 0, ref val, false, true, false);
			SceneManager.UnloadSceneAsync(old_scene);
			Hud_Manager.Hud_Base.Resume_Click();
			old_scene = "";
			new_scene = "";
		}

		public static void StartTp(int index)
		{
			//IL_001a: Unknown result type (might be due to invalid IL or missing references)
			//IL_001f: Unknown result type (might be due to invalid IL or missing references)
			if (index > 0 && index < scene_names.Count)
			{
				Scene activeScene = SceneManager.GetActiveScene();
				old_scene = ((Scene)(ref activeScene)).name;
				new_scene = scene_names[index];
				SceneManager.LoadSceneAsync(new_scene, (LoadSceneMode)1);
				starting_tp = true;
			}
		}

		public static void StartTpToScene(string scene_name)
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_0006: Unknown result type (might be due to invalid IL or missing references)
			Scene activeScene = SceneManager.GetActiveScene();
			old_scene = ((Scene)(ref activeScene)).name;
			new_scene = scene_name;
			SceneManager.LoadSceneAsync(new_scene, (LoadSceneMode)1);
			starting_tp = true;
		}
	}
