		private const int SlotCount = 5;

		private const int HumanFormKey = -1;

		private static readonly int[] AbilityActionIds = new int[5] { 1, 2, 3, 6, 7 };

		private const float PressThrottleSeconds = 0.1f;

		private static InitState state = InitState.NeedsUpdate;

		private static PlayerSkill[] skills = new PlayerSkill[5];

		private static bool appFocus = true;

		private static PlayerChargeManager chargeManager;

		private static UseAbilityProcessor useAbilityProcessor;

		private static Transform playerTransform;

		private static Player rewiredPlayer;

		private static UsingAbilityPlayer abilityState;

		private static int lastFormKey = -1;

		private static readonly Dictionary<int, bool[]> autocastByForm = new Dictionary<int, bool[]>();

		private static bool isSuspended;

		private static string lastSceneName = "";

		private static bool fromAutocast;

		public static Skills_AutoCast instance { get; private set; }

		private static bool GateOn => ModSettings.SkillsAutoCast.DisableInNonCombatZone.Value;

		private static bool PauseOnZoneChangeOn => ModSettings.SkillsAutoCast.PauseOnZoneChange.Value;

		public Skills_AutoCast(IntPtr ptr)
			: base(ptr)
		{
		}

		private void Awake()
		{
			instance = this;
			state = InitState.NeedsUpdate;
		}

		private void OnApplicationFocus(bool hasFocus)
		{
			appFocus = hasFocus;
		}

		private void Update()
		{
			//IL_0191: Unknown result type (might be due to invalid IL or missing references)
			//IL_0196: Unknown result type (might be due to invalid IL or missing references)
			//IL_023a: Unknown result type (might be due to invalid IL or missing references)
			if (!Scenes.IsGameScene())
			{
				ClearAllToggles();
				ResetCachedRefs();
				state = InitState.NeedsUpdate;
				lastSceneName = "";
				return;
			}
			if (Scenes.SceneName != lastSceneName)
			{
				lastSceneName = Scenes.SceneName;
				if (PauseOnZoneChangeOn)
				{
					SuspendAllToggles();
				}
				state = InitState.NeedsUpdate;
			}
			if (state == InitState.NeedsUpdate)
			{
				InitializeSkills();
			}
			if (state != InitState.Ready)
			{
				return;
			}
			CacheRefs();
			if (useAbilityProcessor == null || useAbilityProcessor.IsNullOrDestroyed())
			{
				return;
			}
			CheckFormChange();
			if (state != InitState.Ready)
			{
				return;
			}
			if (!isSuspended && GateOn && InNonCombatZone())
			{
				SuspendAllToggles();
			}
			TryResume();
			bool flag = false;
			bool flag2 = false;
			for (int i = 0; i < 5; i++)
			{
				if (!skills[i].ability.IsNullOrDestroyed())
				{
					HandleInput(i);
					if (skills[i].autocastOn)
					{
						flag = true;
					}
					if (skills[i].held)
					{
						flag2 = true;
					}
				}
			}
			UpdateIconShine();
			if (!flag && !flag2)
			{
				return;
			}
			Transform hitTransform;
			Vector3 targetPosition = GetTargetPosition(out hitTransform);
			int manualHoldIndex = 5;
			if (rewiredPlayer != null && !rewiredPlayer.IsNullOrDestroyed())
			{
				for (int j = 0; j < 5; j++)
				{
					if (!skills[j].ability.IsNullOrDestroyed() && rewiredPlayer.GetButton(AbilityActionIds[j]))
					{
						manualHoldIndex = j;
						break;
					}
				}
			}
			bool firedRisingEdge = false;
			for (int k = 0; k < 5; k++)
			{
				if (!skills[k].ability.IsNullOrDestroyed())
				{
					HandleAutocastSlot(k, manualHoldIndex, targetPosition, hitTransform, ref firedRisingEdge);
				}
			}
		}

		private void InitializeSkills()
		{
			if (Refs_Manager.player_treedata.IsNullOrDestroyed())
			{
				return;
			}
			PlayerAbilityList playerAbilityList = Refs_Manager.player_treedata.playerAbilityList;
			if (playerAbilityList.IsNullOrDestroyed())
			{
				return;
			}
			skills = new PlayerSkill[5];
			for (int i = 0; i < 5; i++)
			{
				Ability val = null;
				try
				{
					val = ((AbilityList)playerAbilityList).getAbility(i);
				}
				catch
				{
				}
				if (!val.IsNullOrDestroyed())
				{
					skills[i] = new PlayerSkill
					{
						ability = val,
						channeled = val.channelled
					};
				}
			}
			ApplyFormStateToSkills(lastFormKey);
			state = InitState.Ready;
		}

		private static void ClearAllToggles()
		{
			autocastByForm.Clear();
			isSuspended = false;
			lastFormKey = -1;
			for (int i = 0; i < 5; i++)
			{
				skills[i].autocastOn = false;
				skills[i].held = false;
				skills[i].nextPressTime = 0f;
			}
		}

		private static void SuspendAllToggles()
		{
			isSuspended = true;
			for (int i = 0; i < 5; i++)
			{
				if (skills[i].held && skills[i].channeled)
				{
					StopChannel(i);
				}
				skills[i].autocastOn = false;
				skills[i].held = false;
				skills[i].nextPressTime = 0f;
			}
		}

		private static void ResumeNow()
		{
			isSuspended = false;
			ApplyFormStateToSkills(lastFormKey);
		}

		private static bool[] GetOrCreateFormState(int formKey)
		{
			if (!autocastByForm.TryGetValue(formKey, out var value))
			{
				value = new bool[5];
				autocastByForm[formKey] = value;
			}
			return value;
		}

		private static void ApplyFormStateToSkills(int formKey)
		{
			if (isSuspended || !autocastByForm.TryGetValue(formKey, out var value))
			{
				return;
			}
			for (int i = 0; i < 5; i++)
			{
				if (!skills[i].ability.IsNullOrDestroyed())
				{
					skills[i].autocastOn = value[i];
				}
			}
		}

		private static bool InNonCombatZone()
		{
			if (string.IsNullOrEmpty(Scenes.SceneName))
			{
				return false;
			}
			try
			{
				return SceneList.IsNonCombatZone(Scenes.SceneName);
			}
			catch
			{
				return false;
			}
		}

		private static void TryResume()
		{
			if (!isSuspended || (GateOn && InNonCombatZone()))
			{
				return;
			}
			if (!PauseOnZoneChangeOn)
			{
				ResumeNow();
			}
			else
			{
				if (rewiredPlayer == null || rewiredPlayer.IsNullOrDestroyed() || IsModifierHeld())
				{
					return;
				}
				for (int i = 0; i < 5; i++)
				{
					if (rewiredPlayer.GetButtonDown(AbilityActionIds[i]))
					{
						ResumeNow();
						break;
					}
				}
			}
		}

		private void CheckFormChange()
		{
			if (Refs_Manager.player_treedata.IsNullOrDestroyed())
			{
				return;
			}
			PlayerAbilityList playerAbilityList = Refs_Manager.player_treedata.playerAbilityList;
			if (playerAbilityList.IsNullOrDestroyed())
			{
				return;
