			public static void Update()
			{
				if (minion_ui.IsNullOrDestroyed())
				{
					return;
				}
				foreach (GameObject spider in spiders)
				{
					if (!spider.IsNullOrDestroyed())
					{
						Summoned component = spider.GetComponent<Summoned>();
						if (component.IsNullOrDestroyed())
						{
							spider.AddComponent<Summoned>();
						}
						UnsummonAfterDelay component2 = spider.GetComponent<UnsummonAfterDelay>();
						if (!component2.IsNullOrDestroyed() && !((Behaviour)component2).enabled)
						{
							((Behaviour)component2).enabled = true;
						}
					}
				}
				Enumerator<MultiMinionCard> enumerator2 = minion_ui.multiMinionCards.GetEnumerator();
				while (enumerator2.MoveNext())
				{
					MultiMinionCard current2 = enumerator2.Current;
					if (((MinionCard)current2).ability.abilityName == "Raise Spider")
					{
						((MinionCard)current2).image.sprite = Icon;
					}
				}
			}

