				if (ability.IsNullOrDestroyed() || prefab_obj.IsNullOrDestroyed())
				{
					return;
				}
				if (Count() < summon_limit)
				{
					if (ability.abilityPrefab.IsNullOrDestroyed())
					{
						ability.abilityPrefab = Object.Instantiate<GameObject>(prefab_obj, Vector3.zero, Quaternion.identity);
					}
					if (!ability.abilityPrefab.IsNullOrDestroyed())
					{
						ability.abilityPrefab.active = true;
						ability.CastAfterDelay(actor.GetComponent<AbilityObjectConstructor>(), target_position, target_position, 0f, (UseType)0, false, (AbilityMutator)null);
					}
				}
				ResetTimer();
			}

			public static int Count()
			{
				int num = 0;
				Enumerator<MultiMinionCard> enumerator = minion_ui.multiMinionCards.GetEnumerator();
				while (enumerator.MoveNext())
				{
					MultiMinionCard current = enumerator.Current;
					if (((MinionCard)current).ability.abilityName == "Raise Spider")
					{
						num += current.currentMinionCount;
					}
				}
				if (num == 0)
				{
					spiders = new List<GameObject>();
				}
				return num;
			}

			public static void ResetTimer()
			{
				foreach (GameObject spider in spiders)
				{
					if (!spider.IsNullOrDestroyed())
					{
						UnsummonAfterDelay component = spider.GetComponent<UnsummonAfterDelay>();
						if (!component.IsNullOrDestroyed() && component.timeRemaining > 0f)
						{
							component.timeRemaining = max_time;
						}
					}
				}
			}
		}

