				int num = Random.Range(Save_Manager.instance.data.NewItems.Headhunter.MinGenerated, Save_Manager.instance.data.NewItems.Headhunter.MaxGenerated + 1);
				for (int i = 0; i < num; i++)
				{
					Buff val = Generate_Random_HHBuff();
					int num2 = (int)Save_Manager.instance.data.NewItems.Headhunter.Stack;
					if (num2 == 0)
					{
						num2 = 1;
						Save_Manager.instance.data.NewItems.Headhunter.Stack = 1f;
					}
					if (val == null)
					{
						continue;
					}
					UpdateBuff(PlayerFinder.getPlayerActor(), val, num2);
					if (!Refs_Manager.summon_tracker.IsNullOrDestroyed())
					{
						Enumerator<Summoned> enumerator = Refs_Manager.summon_tracker.summons.GetEnumerator();
						while (enumerator.MoveNext())
						{
							Summoned current = enumerator.Current;
							UpdateBuff(current.actor, val, num2);
						}
					}
				}
			}

			public static void UpdateBuff(Actor actor, Buff random_buff, int max_stack)
			{
				//IL_020c: Unknown result type (might be due to invalid IL or missing references)
				//IL_0238: Unknown result type (might be due to invalid IL or missing references)
				//IL_0268: Unknown result type (might be due to invalid IL or missing references)
				if (actor.IsNullOrDestroyed())
				{
					return;
				}
				float num = 0f;
				string text = "";
				int stack = 1;
				Enumerator<Buff> enumerator = actor.statBuffs.buffs.GetEnumerator();
				while (enumerator.MoveNext())
				{
					Buff current = enumerator.Current;
					if (!current.name.Contains(random_buff.name))
					{
						continue;
					}
					text = current.name;
					float num2 = 0f;
					if (!GetIsIncrease(current))
					{
						num = current.stat.addedValue;
						if (num < Save_Manager.instance.data.NewItems.Headhunter.AddValue * (float)max_stack)
						{
							num2 = num + Save_Manager.instance.data.NewItems.Headhunter.AddValue;
							stack = (int)(num2 / Save_Manager.instance.data.NewItems.Headhunter.AddValue);
						}
						else
						{
							num2 = Save_Manager.instance.data.NewItems.Headhunter.AddValue * (float)max_stack;
							stack = max_stack;
						}
						random_buff.stat.addedValue = num2;
					}
					else
					{
						num = current.stat.increasedValue;
						if (num < Save_Manager.instance.data.NewItems.Headhunter.IncreasedValue * (float)max_stack)
						{
							num2 = num + Save_Manager.instance.data.NewItems.Headhunter.IncreasedValue;
							stack = (int)(num2 / Save_Manager.instance.data.NewItems.Headhunter.IncreasedValue);
						}
						else
						{
							num2 = Save_Manager.instance.data.NewItems.Headhunter.IncreasedValue * (float)max_stack;
							stack = max_stack;
						}
						random_buff.stat.increasedValue = num2;
					}
					break;
				}
				if (text != "")
				{
					actor.statBuffs.removeBuffsWithName(text);
				}
				actor.statBuffs.addBuff(random_buff.remainingDuration, random_buff.stat.property, random_buff.stat.addedValue, random_buff.stat.increasedValue, random_buff.stat.moreValues, random_buff.stat.tags, random_buff.name);
				if ((Object)(object)actor == (Object)(object)PlayerFinder.getPlayerActor())
				{
					UI.AddBuff(random_buff.name, stack, random_buff.stat.property);
				}
			}

