		public class Events
		{
			public static bool OnKillEvent_Initialized = false;

			private static readonly Action<Ability, Actor> OnKillAction = OnKill;

			public static bool OnMinionKillEvent_Initialized = false;

			private static readonly Action<Summoned, Ability, Actor> OnMinionKillAction = OnMinionKill;

			public static void Init_OnKillEvent()
			{
				if (!Refs_Manager.player_actor.IsNullOrDestroyed() && !((Component)Refs_Manager.player_actor).gameObject.IsNullOrDestroyed())
				{
					AbilityEventListener component = ((Component)Refs_Manager.player_actor).gameObject.GetComponent<AbilityEventListener>();
					if (!component.IsNullOrDestroyed())
					{
						component.onKillEvent += OnKillAction.op_Implicit(OnKillAction);
						OnKillEvent_Initialized = true;
					}
				}
			}

			private static void OnKill(Ability ability, Actor killedActor)
			{
				if (Unique.IsEquipped())
				{
					RandomBuffs.GenerateBuffs();
				}
			}

			public static void Init_OnMinionKillEvent()
			{
				if (!Refs_Manager.player_actor.IsNullOrDestroyed() && !((Component)Refs_Manager.player_actor).gameObject.IsNullOrDestroyed())
				{
					SummonTracker component = ((Component)Refs_Manager.player_actor).gameObject.GetComponent<SummonTracker>();
					if (!component.IsNullOrDestroyed())
					{
						component.minionKillEvent += MinionKillAction.op_Implicit(OnMinionKillAction);
						OnMinionKillEvent_Initialized = true;
					}
				}
			}

			private static void OnMinionKill(Summoned summon, Ability ability, Actor killedActor)
			{
				if (Unique.IsEquipped())
				{
					RandomBuffs.GenerateBuffs();
				}
			}
		}

		public static bool Initialized;

		private bool InGame = false;

		public static Items_HeadHunter instance { get; private set; }

		public Items_HeadHunter(IntPtr ptr)
			: base(ptr)
		{
		}

		private void Awake()
		{
			instance = this;
			SceneManager.sceneLoaded += UnityAction<Scene, LoadSceneMode>.op_Implicit((Action<Scene, LoadSceneMode>)OnSceneLoaded);
		}

		private void Update()
		{
			if (!Assets.Loaded())
			{
				Assets.Load();
			}
			else if (!Initialized)
			{
				Initialized = Config.LoadConfig();
			}
			if (Locales.current != Locales.Selected.Unknow)
			{
				if (!Basic.AddedToBasicList)
				{
					Basic.AddToBasicList();
				}
				if (!Unique.AddedToUniqueList)
				{
					Unique.AddToUniqueList();
				}
				else if (!Unique.AddedToDictionary)
				{
					Unique.AddToDictionary();
				}
			}
			if (!Events.OnKillEvent_Initialized)
			{
				Events.Init_OnKillEvent();
			}
			if (!Events.OnMinionKillEvent_Initialized)
			{
				Events.Init_OnMinionKillEvent();
			}
			if (!UI.buffs_prefab.IsNullOrDestroyed() && UI.buffs_obj.IsNullOrDestroyed())
			{
				UI.Init();
			}
			if (Unique.IsEquipped())
			{
				UI.UpdateBuff();
			}
		}

		private void OnSceneLoaded(Scene scene, LoadSceneMode mode)
		{
			if (Scenes.IsGameScene())
			{
				if (!InGame)
				{
					Events.OnKillEvent_Initialized = false;
					Events.OnMinionKillEvent_Initialized = false;
				}
				InGame = true;
			}
			else if (InGame)
			{
				InGame = false;
			}
		}
	}
