		public class Trigger
		{
			public static Ability[] Abilities;

			private static DateTime[] Times;

			private static bool Initializing;

			private static bool trigger;

			public static void Initialize_SocketedSkills()
			{
				if (Initializing)
				{
					return;
				}
				Initializing = true;
				Abilities = (Ability[])(object)new Ability[3];
				Times = new DateTime[3];
				if (!Refs_Manager.ability_manager.IsNullOrDestroyed())
				{
					int num = 0;
					Enumerator<Ability> enumerator = Refs_Manager.ability_manager.abilities.GetEnumerator();
					while (enumerator.MoveNext())
					{
						Ability current = enumerator.Current;
						if (!current.IsNullOrDestroyed() && num < 3 && (current.abilityName == Save_Manager.instance.data.NewItems.Mjolner.SockectedSkill_0 || current.abilityName == Save_Manager.instance.data.NewItems.Mjolner.SockectedSkill_1 || current.abilityName == Save_Manager.instance.data.NewItems.Mjolner.SockectedSkill_2))
						{
							Abilities[num] = current;
							Times[num] = DateTime.Now;
							num++;
						}
					}
				}
				Initializing = false;
			}

			internal static void SocketedSkills(Actor hitActor)
			{
				//IL_014c: Unknown result type (might be due to invalid IL or missing references)
				//IL_0152: Unknown result type (might be due to invalid IL or missing references)
				if (hitActor.IsNullOrDestroyed() || trigger)
				{
					return;
				}
				trigger = true;
				for (int i = 0; i < Abilities.Length; i++)
				{
					if (Abilities[i].IsNullOrDestroyed() || i >= Times.Length)
					{
						continue;
					}
					bool flag = false;
					double num = Save_Manager.instance.data.NewItems.Mjolner.SocketedCooldown;
					if (num < 1.0)
					{
						num = 1.0;
					}
					if ((DateTime.Now - Times[i]).TotalSeconds > num)
					{
						flag = true;
					}
					if (flag)
					{
						float num2 = Random.Range(Save_Manager.instance.data.NewItems.Mjolner.MinTriggerChance, Save_Manager.instance.data.NewItems.Mjolner.MaxTriggerChance);
						float num3 = Random.Range(0f, 1f);
						if (num3 <= num2)
						{
							float manaCost = Abilities[i].manaCost;
							Abilities[i].manaCost = 0f;
							Abilities[i].castAtTargetFromConstructorAfterDelay(Refs_Manager.player_actor.abilityObjectConstructor, Vector3.zero, hitActor.position(), 0f, (UseType)0);
							Abilities[i].manaCost = manaCost;
						}
						Times[i] = DateTime.Now;
					}
				}
				trigger = false;
			}
		}

		private class Events
		{
			private static bool OnHitEvent_Initialized = false;

			private static readonly Action<Ability, Actor> OnHitAction = OnHit;

			internal static void Update()
			{
				if (!OnHitEvent_Initialized)
				{
					Init_OnHitEvent();
				}
			}

			internal static void Reset()
			{
				OnHitEvent_Initialized = false;
			}

			private static void Init_OnHitEvent()
			{
				if (!Refs_Manager.player_actor.IsNullOrDestroyed() && !((Component)Refs_Manager.player_actor).gameObject.IsNullOrDestroyed())
				{
					AbilityEventListener component = ((Component)Refs_Manager.player_actor).gameObject.GetComponent<AbilityEventListener>();
					if (!component.IsNullOrDestroyed())
					{
						component.onHitEvent += OnHitAction.op_Implicit(OnHitAction);
						OnHitEvent_Initialized = true;
					}
				}
			}

			private static void OnHit(Ability ability, Actor hitActor)
			{
				if (!Refs_Manager.player_actor.IsNullOrDestroyed() && Refs_Manager.player_actor.itemContainersManager.hasUniqueEquipped(Unique.unique_id) && ((Stats)Refs_Manager.player_actor.stats).GetAttributeValue((Attribute)0) >= Save_Manager.instance.data.NewItems.Mjolner.StrRequirement && ((Stats)Refs_Manager.player_actor.stats).GetAttributeValue((Attribute)2) >= Save_Manager.instance.data.NewItems.Mjolner.IntRequirement)
				{
					Trigger.SocketedSkills(hitActor);
				}
			}
		}

		private bool InGame = false;

		public static Items_Mjolner instance { get; private set; }

		public Items_Mjolner(IntPtr ptr)
			: base(ptr)
		{
		}

		private void Awake()
		{
			instance = this;
			SceneManager.sceneLoaded += UnityAction<Scene, LoadSceneMode>.op_Implicit((Action<Scene, LoadSceneMode>)OnSceneLoaded);
		}

		private void Update()
		{
			Icon.Update();
			Unique.Update();
			Events.Update();
		}

		private void OnSceneLoaded(Scene scene, LoadSceneMode mode)
		{
			if (Scenes.IsGameScene())
			{
				Trigger.Initialize_SocketedSkills();
				if (!InGame)
				{
					Events.Reset();
				}
				InGame = true;
			}
			else if (InGame)
			{
				InGame = false;
			}
		}
	}
