			public unsafe static async Task SetBlessings(List<Data.Blessings_structure> blessings)
			{
				Main.logger_instance.Msg("SetBlessings();");
				if (Refs_Manager.player_data_tracker.IsNullOrDestroyed() || Refs_Manager.game_uibase.IsNullOrDestroyed())
				{
					return;
				}
				Hud_Manager.Hud_Base.Resume_Click();
				while (Hud_Manager.IsPauseOpen())
				{
					await Task.Delay(TimeSpan.FromSeconds(1.0));
				}
				Main.logger_instance.Msg("Hud Closed");
				List<TimelineID> timelines_id = new List<TimelineID>
				{
					(TimelineID)1,
					(TimelineID)2,
					(TimelineID)3,
					(TimelineID)4,
					(TimelineID)5,
					(TimelineID)6,
					(TimelineID)7,
					(TimelineID)8,
					(TimelineID)9,
					(TimelineID)10
				};
				foreach (Data.Blessings_structure b in blessings)
				{
					if (b.timeline >= timelines_id.Count)
					{
						continue;
					}
					TimelineID selected_timeline = timelines_id[b.timeline];
					Main.logger_instance.Msg("timeline = " + ((object)(*(TimelineID*)(&selected_timeline))/*cast due to .constrained prefix*/).ToString());
					if (!BlessingRewardPanelManager.instance.IsNullOrDestroyed())
					{
						Main.logger_instance.Msg("Set option");
						OneItemContainer container = ((Il2CppObjectBase)((ItemContainerUI)BlessingRewardPanelManager.instance.blessingOptions[0]).Container).TryCast<OneItemContainer>();
						if (!container.IsNullOrDestroyed())
						{
							((OneSlotItemContainer)container).content = new ItemContainerEntry(b.data, new Vector2Int(0, 0), new Vector2Int(1, 1), 1);
							Refs_Manager.game_uibase.OpenBlessingOptions(selected_timeline, 0, 3);
							Main.logger_instance.Msg("Reward panel Open");
							BlessingRewardPanelManager.instance._selectedOption = 0;
							BlessingRewardPanelManager.instance.ReplaceButton();
							BlessingRewardPanelManager.instance.ConfirmSelection();
							Refs_Manager.game_uibase.CloseBlessingOptions();
							Main.logger_instance.Msg("Reward panel Closed");
						}
					}
				}
			}

