			public static async Task Load(string url)
			{
				loaded = false;
				if (url.Contains("https://maxroll.gg/last-epoch/planner/"))
				{
					HttpResponseMessage response = await new HttpClient().GetAsync(url);
					response.EnsureSuccessStatusCode();
					string jsonResponse = await response.Content.ReadAsStringAsync();
					string profile = url.Split('/')[^1];
					if (profile.Contains("#"))
					{
						selected_profile = Convert.ToInt32(profile.Split('#')[1]) - 1;
						string p2 = profile.Split('#')[0];
						profile = p2;
					}
					else
					{
						selected_profile = 0;
					}
					string json = "";
					string[] r = jsonResponse.Split('>');
					string[] array = r;
					foreach (string s in array)
					{
						if (s.Contains(profile))
						{
							string s2 = s.Split('<')[0];
							string remove = "window.__remixContext = ";
							json = s2.Substring(remove.Length, s2.Length - remove.Length - 1);
							break;
						}
					}
					if (json != "")
					{
						root = JsonConvert.DeserializeObject<Json.Root>(json);
						data = JsonConvert.DeserializeObject<Json.Data>(root.State.LoaderData.LastEpochPlannerById.Profile.Data);
						loaded = true;
					}
				}
				else
				{
					Main.logger_instance.Error("Not a Maxroll URL");
				}
			}

			public static void Update()
			{
				updating = true;
				profile_names = Get.Profile_Names();
				build_name = Get.Build_Name();
				autor_name = Get.Autor_UserName();
				youtube = false;
				youtube_url = "";
				if (root.State.LoaderData.LastEpochPlannerById.Metadata.AuthorYoutube != "")
				{
					youtube = true;
					youtube_url = root.State.LoaderData.LastEpochPlannerById.Metadata.AuthorYoutube;
				}
				twitch = false;
				twitch_url = "";
				if (root.State.LoaderData.LastEpochPlannerById.Metadata.AuthorTwitch != "")
				{
					twitch = true;
					twitch_url = root.State.LoaderData.LastEpochPlannerById.Metadata.AuthorTwitch;
				}
				class_name = Get.Character_Class();
				character_level = Get.Character_Level();
				nb_items = Get.Nb_Items();
				nb_idols = Get.Nb_Idols();
				nb_blessings = Get.Nb_Blessings();
				nb_passives = Get.Nb_Passives();
				nb_weavertree = Get.Nb_WeaverTree();
				mainskill_name = root.State.LoaderData.LastEpochPlannerById.Profile.Mainset;
				foreach (Ability item in Resources.FindObjectsOfTypeAll<Ability>())
				{
					if (((Object)item).name == mainskill_name)
					{
						mainskill_icon = item.abilitySprite;
						break;
					}
				}
				string[] array = new string[5] { "", "", "", "", "" };
				int num = 0;
				foreach (string specializedSkill in data.Profiles[selected_profile].SpecializedSkills)
				{
					if (num < array.Length)
					{
						array[num] = specializedSkill;
					}
					num++;
				}
				specialized_names = new string[5] { "", "", "", "", "" };
				specialized_ids = new string[5] { "", "", "", "", "" };
				specialized_ability = (Ability[])(object)new Ability[5];
				specialized_icons = (Sprite[])(object)new Sprite[5];
				num = 0;
				string[] array2 = array;
				foreach (string text in array2)
				{
					foreach (Ability item2 in Resources.FindObjectsOfTypeAll<Ability>())
					{
						if (((Object)item2).name == text)
						{
							specialized_names[num] = item2.abilityName;
							specialized_ids[num] = item2.playerAbilityID;
							specialized_ability[num] = item2;
							specialized_icons[num] = item2.abilitySprite;
							break;
						}
					}
					num++;
				}
				active_names = new string[5] { "", "", "", "", "" };
				active_ability = (Ability[])(object)new Ability[5];
				active_icons = (Sprite[])(object)new Sprite[5];
				num = 0;
				foreach (string activeSkill in data.Profiles[selected_profile].ActiveSkills)
				{
					foreach (Ability item3 in Resources.FindObjectsOfTypeAll<Ability>())
					{
						if (((Object)item3).name == activeSkill)
						{
							active_names[num] = item3.abilityName;
							active_ability[num] = item3;
							active_icons[num] = item3.abilitySprite;
							break;
						}
					}
					num++;
				}
				Hud_Manager.Content.Maxroll.Show();
				updating = false;
			}

