			public static void Load_Equipments()
			{
				if (selected_profile <= -1)
				{
					return;
				}
				Json.Profile profile = data.Profiles[selected_profile];
				List<int> list = new List<int>();
				list.Add(Functions.ObjectToInt(profile.Items.Body));
				list.Add(Functions.ObjectToInt(profile.Items.Feet));
				list.Add(Functions.ObjectToInt(profile.Items.Finger1));
				list.Add(Functions.ObjectToInt(profile.Items.Finger2));
				list.Add(Functions.ObjectToInt(profile.Items.Hands));
				list.Add(Functions.ObjectToInt(profile.Items.Head));
				list.Add(Functions.ObjectToInt(profile.Items.Neck));
				list.Add(Functions.ObjectToInt(profile.Items.Offhand));
				list.Add(Functions.ObjectToInt(profile.Items.Relic));
				list.Add(Functions.ObjectToInt(profile.Items.Waist));
				list.Add(Functions.ObjectToInt(profile.Items.Weapon));
				list.Add(Functions.ObjectToInt(profile.Items.Altar));
				foreach (KeyValuePair<int, Json.Item> item in data.Items)
				{
					if (list.Contains(item.Key))
					{
						Functions.DropItem(Functions.MakeItem(item.Value.ItemType, item.Value.SubType, item.Value.Implicits, item.Value.Affixes, item.Value.SealedAffix, item.Value.PrimordialAffix, item.Value.UniqueID, item.Value.UniqueRolls, item.Value.Corrupted, item.Value.CorruptedAffixes));
					}
				}
			}

			public static void Load_Idols()
			{
				if (selected_profile <= -1)
				{
					return;
				}
				List<int> list = new List<int>();
				foreach (object idol in data.Profiles[selected_profile].Idols)
				{
					list.Add(Functions.ObjectToInt(idol));
				}
				foreach (KeyValuePair<int, Json.Item> item in data.Items)
				{
					if (list.Contains(item.Key))
					{
						Functions.DropItem(Functions.MakeItem(item.Value.ItemType, item.Value.SubType, item.Value.Implicits, item.Value.Affixes, item.Value.SealedAffix, item.Value.PrimordialAffix, item.Value.UniqueID, item.Value.UniqueRolls, item.Value.Corrupted, item.Value.CorruptedAffixes));
					}
				}
			}

			public static async void Load_Blessings()
			{
				Main.logger_instance.Msg("Load_Blessings();");
				if (selected_profile <= -1)
				{
					return;
				}
				int i = 0;
				List<Blessings_structure> blessings = new List<Blessings_structure>();
				foreach (Json.Blessing item in data.Profiles[selected_profile].Blessings)
				{
					if (!item.IsNullOrDestroyed())
					{
						Main.logger_instance.Msg("i = " + i);
						blessings.Add(new Blessings_structure
						{
							timeline = i,
							data = Functions.MakeItem(item.ItemType, item.SubType, item.Implicits, null, null, null, null, null, corrupted: false, null)
						});
					}
					i++;
				}
				await Functions.SetBlessings(blessings);
			}

