				((TreeData)Refs_Manager.player_treedata.passiveTree).nodes.Clear();
				foreach (int item in profile.Passives.History)
				{
					bool flag = false;
					Enumerator<NodeData> enumerator2 = ((TreeData)Refs_Manager.player_treedata.passiveTree).nodes.GetEnumerator();
					while (enumerator2.MoveNext())
					{
						NodeData current2 = enumerator2.Current;
						if (current2.id == item)
						{
							byte pointsAllocated = current2.pointsAllocated;
							current2.pointsAllocated = (byte)(pointsAllocated + 1);
							flag = true;
							break;
						}
					}
					if (!flag)
					{
						((TreeData)Refs_Manager.player_treedata.passiveTree).nodes.Add(new NodeData((byte)item, (byte)1));
