			public static void Load_SkillTree(int index, int slot)
			{
				//IL_01b3: Unknown result type (might be due to invalid IL or missing references)
				//IL_01bd: Expected O, but got Unknown
				if (selected_profile <= -1)
				{
					return;
				}
				Json.Profile profile = data.Profiles[selected_profile];
				if (Refs_Manager.player_treedata.IsNullOrDestroyed())
				{
					return;
				}
				string text = specialized_ids[index];
				if (!(text != ""))
				{
					return;
				}
				Json.NodePoint nodePoint = null;
				foreach (KeyValuePair<string, Json.NodePoint> item in profile.Skill)
				{
					if (item.Key == text)
					{
						nodePoint = item.Value;
						break;
					}
				}
				Ability specialisedAbilityInSlot = Refs_Manager.player_treedata.getSpecialisedAbilityInSlot((byte)slot);
				if (!specialisedAbilityInSlot.IsNullOrDestroyed())
				{
					Refs_Manager.player_treedata.Despecialise(specialisedAbilityInSlot, true);
				}
				Refs_Manager.player_treedata.Specialise(specialized_ability[index], (byte)slot, true);
				Enumerator<SkillTreeData> enumerator2 = Refs_Manager.player_treedata.specialisedSkillTrees.GetEnumerator();
				while (enumerator2.MoveNext())
				{
					TreeData current2 = (TreeData)(object)enumerator2.Current;
					if (!(current2.treeID == text))
					{
						continue;
					}
					foreach (int item2 in nodePoint.History)
					{
						bool flag = false;
						Enumerator<NodeData> enumerator4 = current2.nodes.GetEnumerator();
						while (enumerator4.MoveNext())
						{
							NodeData current4 = enumerator4.Current;
							if (current4.id == item2)
							{
								byte pointsAllocated = current4.pointsAllocated;
								current4.pointsAllocated = (byte)(pointsAllocated + 1);
								flag = true;
								break;
							}
						}
						if (!flag)
						{
							current2.nodes.Add(new NodeData((byte)item2, (byte)1));
						}
					}
					SkillTreeData val = ((Il2CppObjectBase)current2).TryCast<SkillTreeData>();
					if (!val.IsNullOrDestroyed())
					{
						val.level = 20;
						val.abilityXp = 999999999;
						Refs_Manager.player_treedata.saveSpecialisedSkillData(val);
					}
					break;
				}
			}

			public static void Load_ActiveSkills()
			{
				if (selected_profile <= -1 || Refs_Manager.player_treedata.IsNullOrDestroyed())
				{
					return;
				}
				for (int i = 0; i < ((ComboAbilityList)Refs_Manager.player_treedata.playerAbilityList).equippedAbilities.Count; i++)
				{
					if (i < active_ability.Length && !active_ability[i].IsNullOrDestroyed() && (Object)(object)active_ability[i] != (Object)(object)((ComboAbilityList)Refs_Manager.player_treedata.playerAbilityList).equippedAbilities[i])
					{
						((AbilityList)Refs_Manager.player_treedata.playerAbilityList).setAbility(active_ability[i], i, false, false);
					}
				}
			}
		}

