		public Maxroll_import(IntPtr ptr)
			: base(ptr)
		{
		}

		private void Awake()
		{
			instance = this;
		}

		private void Update()
		{
			if (Data.loaded && (Data.root.IsNullOrDestroyed() || Data.data.IsNullOrDestroyed()))
			{
				Data.loaded = false;
				if (Hud_Manager.Content.Maxroll.show && !Data.updating)
				{
					Data.updating = true;
					Hud_Manager.Content.Maxroll.Hide();
					Data.updating = false;
				}
			}
			if (Data.loaded && !Data.updating && !Hud_Manager.Content.Maxroll.show && !Data.root.IsNullOrDestroyed() && !Data.data.IsNullOrDestroyed() && Data.selected_profile > -1)
			{
				Data.Update();
			}
		}
	}
