		public Items_AutoStore_WithTimer(IntPtr ptr)
			: base(ptr)
		{
		}

		private void Awake()
		{
			instance = this;
		}

		private void Update()
		{
			if (Scenes.IsGameScene() && !Save_Manager.instance.IsNullOrDestroyed() && !Refs_Manager.InventoryPanelUI.IsNullOrDestroyed())
			{
				if (Save_Manager.instance.data.Items.Pickup.Enable_AutoStore_Timer)
				{
					if (!running)
					{
						StartTime = DateTime.Now;
						running = true;
					}
					if (running && GetElapsedTime() > (double)Save_Manager.instance.data.Items.Pickup.AutoStore_Timer && !Refs_Manager.InventoryPanelUI.IsNullOrDestroyed())
					{
						Refs_Manager.InventoryPanelUI.StoreMaterialsButtonPress();
						running = false;
					}
				}
			}
			else
			{
				running = false;
			}
		}

		private double GetElapsedTime()
		{
			LastTime = DateTime.Now;
			return (LastTime - StartTime).TotalSeconds;
		}
	}
