	[RegisterTypeInIl2Cpp]
	public class Fix_LowFPS : MonoBehaviour
	{
		public static bool check_fps;

		public static bool need_fix;

		public static bool fixing;

		public static Fix_LowFPS instance { get; private set; }

		public Fix_LowFPS(IntPtr ptr)
			: base(ptr)
		{
		}

		private void Awake()
		{
			instance = this;
		}

		private void Update()
		{
			if (!Scenes.IsGameScene())
			{
				check_fps = true;
				return;
			}
			if (check_fps && !Refs_Manager.game_uibase.IsNullOrDestroyed())
			{
				int fps = GetFps();
				if (fps > -1 && fps < 20)
				{
					need_fix = true;
				}
				check_fps = false;
			}
			if (need_fix && !Refs_Manager.game_uibase.IsNullOrDestroyed() && !Hud_Manager.hud_object.IsNullOrDestroyed())
			{
				if (!Hud_Manager.IsPauseOpen())
				{
					fixing = true;
					Refs_Manager.game_uibase.openMenu(false);
				}
				else if (fixing)
				{
					fixing = false;
					need_fix = false;
					((UnityEvent)Hud_Manager.Hud_Base.Btn_Resume.onClick).Invoke();
					check_fps = true;
				}
			}
		}

		private int GetFps()
		{
			int result = -1;
			if (!Refs_Manager.game_uibase.IsNullOrDestroyed() && !Refs_Manager.game_uibase.fpsDisplay.IsNullOrDestroyed())
			{
				Refs_Manager.game_uibase.fpsDisplay.UpdateUI();
				if (((TMP_Text)Refs_Manager.game_uibase.fpsDisplay.display).text.Split(' ').Length > 2)
				{
					string value = ((TMP_Text)Refs_Manager.game_uibase.fpsDisplay.display).text.Split(' ')[3];
					result = Convert.ToInt32(value);
				}
				else if (((TMP_Text)Refs_Manager.game_uibase.fpsDisplay.display).text.Split(' ').Length != 0)
				{
					string value2 = ((TMP_Text)Refs_Manager.game_uibase.fpsDisplay.display).text.Split(' ')[1];
					result = Convert.ToInt32(value2);
				}
			}
			return result;
		}
	}
