	public class ZoneScaling
	{
		[HarmonyPatch(typeof(ZoneInfoManager), "SetZoneLevel")]
		public class SetZoneLevelPatch
		{
			[HarmonyPostfix]
			private static void Postfix(int level, bool alwaysUpdateClient)
			{
				try
				{
					if (_isOverriding || !Scenes.IsGameScene() || !ModSettings.Difficulty.ScaleZoneToPlayer.Value)
					{
						return;
					}
					_lastOriginalZoneLevel = level;
					int playerLevel = GetPlayerLevel();
					if (playerLevel <= 0 || playerLevel <= level)
					{
						return;
					}
					_isOverriding = true;
					try
					{
						ZoneInfoManager.SetZoneLevel(playerLevel, true);
					}
					finally
					{
						_isOverriding = false;
					}
				}
				catch
				{
				}
			}
		}

		[HarmonyPatch(typeof(ExperienceTracker), "GainExpFromEnemyOrMote")]
		public class XpCapFromEnemyPatch
		{
			[HarmonyPrefix]
			private static bool Prefix(ExperienceTracker __instance, ref long expAmount)
			{
				try
				{
					return HandleXpCap(__instance, ref expAmount);
				}
				catch
				{
					return true;
				}
			}
		}

		[HarmonyPatch(typeof(ExperienceTracker), "GainExpDirect")]
		public class XpCapDirectPatch
		{
			[HarmonyPrefix]
			private static bool Prefix(ExperienceTracker __instance, ref long expAmount)
			{
				try
				{
					return HandleXpCap(__instance, ref expAmount);
				}
				catch
				{
					return true;
				}
			}
		}

		internal static int _lastOriginalZoneLevel = -1;

		private static bool _isOverriding = false;

		private static int _xpBlockCount = 0;

		private static int GetPlayerLevel()
		{
			try
			{
				if (!Refs_Manager.player_data.IsNullOrDestroyed())
				{
					return Refs_Manager.player_data.Level;
				}
			}
			catch
			{
			}
			return 0;
		}

		private static int GetZoneLevel()
		{
			try
			{
				return ZoneInfoManager.ZoneLevel;
			}
			catch
			{
				return 0;
			}
		}

		private static bool HandleXpCap(ExperienceTracker tracker, ref long expAmount)
		{
			if (!Scenes.IsGameScene())
			{
				return true;
			}
			if (!ModSettings.Difficulty.CapLevelToZone.Value)
			{
				return true;
			}
			int num = ((_lastOriginalZoneLevel > 0) ? _lastOriginalZoneLevel : GetZoneLevel());
			if (num <= 0)
			{
				return true;
			}
			if (tracker.CurrentLevel < num)
			{
				return true;
			}
			long currentExperience = tracker.CurrentExperience;
			long nextLevelExperience = tracker.NextLevelExperience;
			if (currentExperience + expAmount < nextLevelExperience)
			{
				return true;
			}
			long num2 = nextLevelExperience - currentExperience - 1;
			if (num2 <= 0)
			{
				_xpBlockCount++;
				return false;
			}
			expAmount = num2;
			return true;
		}
	}
