			foreach (UIWaypointStandard item in Object.FindObjectsOfType<UIWaypointStandard>())
			{
				if (((UIWaypoint)item).sceneName == name && ((UIWaypoint)item).gate == gate)
				{
					result = item;
					break;
				}
			}
			return result;
