				{
					public struct tabs
					{
						public List<string> names;
					}
				}

				public static readonly string base_path = Directory.GetCurrentDirectory() + "\\Mods\\LastEpoch_Hud\\QuadStashs\\";

				public static string filename = "QuadStashs.json";

				public static string path = "";

				public static Structures.tabs UserTabs = default(Structures.tabs);

				public static void DefaultConfig()
				{
					Main.logger_instance.Msg("QuadStashs : Make DefaultConfig");
					UserTabs = new Structures.tabs
					{
						names = new List<string>()
					};
				}

				public static void Load()
				{
					Main.logger_instance.Msg("QuadStashs : Try to Load : " + path + filename);
					if (!File.Exists(path + filename))
					{
						DefaultConfig();
						Save();
					}
					if (File.Exists(path + filename))
					{
						try
						{
							UserTabs = JsonConvert.DeserializeObject<Structures.tabs>(File.ReadAllText(path + filename));
							Main.logger_instance.Msg("QuadStashs : Loaded");
						}
						catch
						{
							Main.logger_instance.Error("QuadStashs : Error loading file : " + path + filename);
						}
					}
				}

				public static void Save()
				{
					Main.logger_instance.Msg("QuadStashs : Save : " + path + filename);
					string contents = JsonConvert.SerializeObject((object)UserTabs, (Formatting)1);
					if (!Directory.Exists(path))
					{
						Directory.CreateDirectory(path);
					}
					if (File.Exists(path + filename))
					{
						File.Delete(path + filename);
					}
					File.WriteAllText(path + filename, contents);
				}
			}
		}

